window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_031"]={"n":"尤侗","dyn":"清","poems":[{"t":"十六字令 梦","f":"古风","c":["春夜梦，香魂花影红。","无人见，啼笑月明中。"]},{"t":"忆王孙 其一 怀卿谋","f":"古风","c":["秋风袅袅洞庭波。","暮雨湛湛落败荷。","数遍相思今夜多。","夜如何？","独倚南楼一雁过。"]},{"t":"忆王孙 其二 闺怨","f":"古风","c":["春愁脉脉损铅华。","独自妆成坐碧纱。","荡子经年不到家。","隔天涯。","一夜相思杨白花。"]},{"t":"忆王孙 其三 闺情","f":"古风","c":["一春心事付眉尖。","小院无人风雨纤。","落尽桃花倚绣奁。","思淹淹。","燕子归家不卷帘。"]},{"t":"转应曲 其一 春雨","f":"古风","c":["春雨，春雨。","花上泪痕几许。","东风吹到纱窗。","日日愁来断肠。","肠断，肠断。","又续新愁一半。"]},{"t":"转应曲 其二 中秋雨","f":"古风","c":["秋雨，秋雨。","滴碎琼宫霓羽。","清歌妙舞阑珊。","阵阵霜风夜寒。","寒夜，寒夜。","寄语嫦娥睡罢。"]},{"t":"后庭花 闺怨","f":"古风","c":["绿阶花影翻。","红栏燕语喧。","明镜嫌眉瘦，空床厌梦烦。","倚黄昏、东风无赖，又来吹断魂。"]},{"t":"如梦令 其一 柳絮","f":"古风","c":["一捻宫腰削素，独舞朱楼深处。","有意送春归，也向天涯飞去。","且住，且住，为道章台日暮。"]},{"t":"如梦令 其二 病呓","f":"古风","c":["半似醉乡情趣，半似睡乡心绪。","怯怯病中身，则待放他何处？","无据，无据，一任西风吹去。"]},{"t":"如梦令 其三 戏赠小伶","f":"古风","c":["六幅裙儿半挂，八字眉儿半画。","笑问若耶人，何事西施未嫁。","长夜，长夜，为语新妆休卸。"]},{"t":"如梦令 其四 春梦","f":"古风","c":["春梦偶然失晓，催起数声娇鸟。","软立倚郎肩，宿黛无心重扫。","罢了，罢了，粗服乱头都好。"]},{"t":"如梦令 其五 题王阮亭雨花园","f":"古风","c":["晏坐袈裟垂地，玉蕊从空飞坠。","摩诘转王维，天女自然游戏。","如是，如是，应证雨花三昧。"]},{"t":"长相思 其一 捲帘","f":"古风","c":["朝捲帘，暮捲帘。","帘捲西风风捲烟。","烟寒风雨寒。","倚栏杆，泪栏杆。","听尽哀鸿听怨蝉。","愁魂飞暮天。"]},{"t":"长相思 其二 春闺","f":"古风","c":["花飞飞，絮飞飞。","绿上眉山红上衣，妆楼日又西。","蝶飞飞，燕飞飞。","飞向雕檐等伴栖，吹箫人不归。"]},{"t":"归自谣 春思","f":"古风","c":["春命短，寒食雨来芳草满。","梨花梦去东风懒。","惜春人倚雕栏畔。","腰肢剪。","流莺又把闲愁管。"]},{"t":"醉太平 山中","f":"古风","c":["山中小园，园中小山。","闲闲十亩之间。","与白鸥往还。","竹枝一竿。","柳枝一弯。","新来添设花栏。","唤橐驼种兰。"]},{"t":"醉公子 本意","f":"五言律诗","c":["何处贪杯酒。","愁杀闺中妇。","尚喜晚还家。","刚留一盏茶。","扶得和衣睡。","冷却鸳鸯被。","不敢骂檀郎。","喃喃咒杜康。"]},{"t":"昭君怨 其一 吊腊梅","f":"古风","c":["昨夜风鞭雨打。","金屋晓来飘瓦。","尺土葬鹅衣。","哭江妃。","正是天寒日暮。","空谷佳人何处。","云鬓惜馀香。","试啼妆。"]},{"t":"昭君怨 其二 春尽","f":"古风","c":["不见落花飞絮，满目土风沙雨。","飘泊可怜人，奈何春。","地下杳无消息，盼断画衣香舄。","百日掩青帘，梦江南。"]},{"t":"醉花间 春闺","f":"古风","c":["兰汤沐。","湘裙束。","懒把秋千蹴。","侬自理秦筝，郎自歌吴曲。","花冠一笑偏，翠袖三薰足。","芙蓉帐底眠，春梦同郎续。"]},{"t":"酒泉子 离情","f":"古风","c":["月白风清。","今夜谁家住去。","过长亭，接短渡。","傍孤城。","知君马上听鸡鸣。","妾也朝朝早起。","剔残灯，空庭里。","拜三星。"]},{"t":"点绛唇 其一 绿荫","f":"古风","c":["梦破帘开，隔墙谡谡风声乱。","徘徊池畔。","绿影浮波面。","闭鸟藏花，收拾春光暗。","遮不遍。","新愁一段。","缭绕天涯散。"]},{"t":"点绛唇 其二 杨花","f":"古风","c":["新绿排衙。","问伊何事轻妆卸。","夭斜顽耍。","惹得黄鹂骂。","无主东风，来去随他罢。","怜今夜。","落红偷嫁。","同宿雕栏下。"]},{"t":"点绛唇 其三 秋海棠","f":"古风","c":["空谷佳人，淡红衫子天然艳。","风清露浅。","脉脉凝啼眼。","恰似伤秋，倚徙湖山遍。","怜谁伴。","重帘不捲。","有个人肠断。"]},{"t":"点绛唇 其四 玉簪花","f":"古风","c":["梦草凄凉，汉宫遗下搔头玉。","淡妆素束。","一顾倾红绿。","清露晨流，仿佛香盈掬。","娱幽独。","广寒留宿。","疑舞霓裳曲。"]},{"t":"春光好 春闺","f":"古风","c":["掩绣阁，镜台封。","鬓云松。","聊聊私语小窗中。","骂春风。","整日恹恹沉睡，侍儿问怎朦胧。","却是背人偷揾泪，枕痕红。"]},{"t":"女冠子 美人走马","f":"古风","c":["青楼年少，走马章台驰道。","倚逍遥。","急雨桃花滚，轻风燕子骄。","春芽拥翠髻，香汗发红潮。","辔儿跑不住，抱鞍桥。"]},{"t":"浣溪沙 其一 春闺","f":"七言古诗","c":["日影笼烟小阁明，侍儿初掠晓妆成。","画楼何处又歌声。","故掩珠帘惊燕燕，戏抛红豆打莺莺。","晚来独傍落花行。"]},{"t":"浣溪沙 其二 美人醉","f":"七言古诗","c":["小盏低斟不当差，粉腮红晕早堆霞。","春风带雨颤桃花。","强对檀郎妆挣挫，慢扶小玉露夭斜。","和衣睡倒太娇些。"]},{"t":"浣溪沙 其三 马上见","f":"七言古诗","c":["胜裤新裁蝉翼纱，锦靿自织凤头靴。","春风不耐碧油车。","金步摇飞金勒动，玉跳脱袅玉鞭斜。","满堤青草衬红霞。"]},{"t":"浣溪沙 有客为王校书索赠漫题二阕其字浣若为调浣溪纱其名西也以西字为韵 其四","f":"七言古诗","c":["闻道王娘旧姓西，采莲重出若耶溪。","淡妆羞学捧心啼。","春水锦帆娇白纻，秋风香径印红泥。","昵郎子夜醉乌栖。"]},{"t":"浣溪沙 有客为王校书索赠漫题二阕其字浣若为调浣溪纱其名西也以西字为韵 其五","f":"七言古诗","c":["家住阊门西复西，凤凰桥上夜乌啼。","绿杨巷曲画帘低。","宛转腰身飞乳燕，聪明性格点灵犀。","粉墙拂袖待留题。"]},{"t":"浣溪沙 清明悼亡二首 其六","f":"七言古诗","c":["陌上家家挂纸钱，东风客舍泪潸然。","难携杯酒滴重泉。","朱户几人同插柳，青山何事尚含烟。","江南梦绕断肠天。"]},{"t":"浣溪沙 清明悼亡二首 其七","f":"七言古诗","c":["少女长安歌踏春，鸾靴翠袜已成尘。","棠梨时候独沾巾。","宫草几年堆燕冢，土花终夜照鱼灯。","君王犹自望昭陵。"]},{"t":"浣溪沙 其八 题陈其年小影","f":"七言古诗","c":["侧帽轻衫古意多，乌丝襕写懊侬歌。","红儿解唱定风波。","翠管吟残浇一斗，玉箫吹破敛双蛾。","酒阑曲罢奈髯何。"]},{"t":"伊川令 和范夫人韵","f":"古风","c":["空房夜夜垂罗幕。","雁柱抛弦索。","又报海棠零落。","香径欲行还却。","红腮枕上羞托。","知郎春梦绕天涯，不肯到、秋千院落。"]},{"t":"菩萨蛮 春愁二首 其一","f":"古风","c":["鹦哥啄碎花须落，晓风低弄秋千索。","刚上一重楼，青山又送愁。","几番寒食雨，柳絮依人舞。","春梦晚归家，小池闻暮蛙。"]},{"t":"菩萨蛮 春愁二首 其二","f":"古风","c":["春风婀娜飘帘幕，玉钩踏破花阴薄。","绿柳旧长堤，王孙骄马嘶。","误听新燕语，倚遍栏杆午。","权把泪痕收，东君不解愁。"]},{"t":"菩萨蛮 其三 听雨","f":"古风","c":["雨声碎滴琅玕竹，风声轻戛珊瑚玉。","月影又模糊，和烟上鹧鸪。","湿萤游古屋，蟋蟀悲秋菊。","罗帐蕙香残，幽人晓梦寒。"]},{"t":"菩萨蛮 无题八首 其四","f":"古风","c":["画帘捲断珊瑚索，绣床小梦随风落。","残月杏花堤，晓莺恰恰啼。","美人和笑立，露叶牵衣湿。","待得侍儿来，妆奁一半开。"]},{"t":"菩萨蛮 无题八首 其五","f":"古风","c":["乌衣双燕穿帘舞，衔花故坠金钗股。","陌上柳丝飞，锦屏人未归。","小窗沉昼闭，山枕留香睡。","春梦杳如烟，知他向那边。"]},{"t":"菩萨蛮 无题八首 其六","f":"古风","c":["竹鸠唤起斜阳梦，杨花倒挂金泥凤。","独自摘青梅，鞋弓印翠苔。","罗衫薄不绾，衬得东风软。","一捻小香脂，无端蜂蝶知。"]},{"t":"菩萨蛮 无题八首 其七","f":"古风","c":["花台日暮莺辞去，暖风吹散胭脂雨。","春困晚梳头，珠帘不上钩。","乱红随地扫，又见宜男草。","半醉倚残妆，花间待阮郎。"]},{"t":"菩萨蛮 无题八首 其八","f":"古风","c":["梨花带雨飘香雪，乱蛙啼出西窗月。","庭砌绿阴浓，罗衣惹暮风。","画梁新燕乳，宿梦呢喃语。","唤我掩湘帘，夜深清露寒。"]},{"t":"菩萨蛮 无题八首 其九","f":"古风","c":["香兰笑向银屏吐，小蛮起作回风舞。","日静绿纱空，美人春梦中。","箫声吹月白，柳带笼烟碧。","芳草满江南，相思一夜深。"]},{"t":"菩萨蛮 无题八首 其十","f":"古风","c":["疏风细雨和春语，扁舟欲载花魂去。","燕子不归家，盼他午日斜。","落红一晌颤，界破残妆面。","收拾护花铃，鹦哥报压惊。"]},{"t":"菩萨蛮 无题八首 其十一","f":"古风","c":["马蹄踏遍天涯草，杜鹃啼破东风小。","花落碧栏桥，翠楼红袖招。","断香随路宿，懊恼枝头绿。","春去不须留，担他一段愁。"]},{"t":"菩萨蛮 其十二 午日","f":"古风","c":["彩线斜袅金跳脱，篆符戏绾同心结。","酌酒劝檀郎，蒲花衬口香。","兰汤初罢浴，窗外调雊?。","刚抹守宫斑，明朝点点残。"]},{"t":"菩萨蛮 夏闺二首 其十三","f":"古风","c":["一阶芳草茸茸绿，乱飞蛱蝶无人扑。","欲摘小蔷薇，嫌他棘刺衣。","昼长停绣谱，私共双鬟语。","心怯越梅酸，只将纤手抟。"]},{"t":"菩萨蛮 夏闺二首 其十四","f":"古风","c":["锦葵花底弹棋坐，一帘明月留人卧。","粉汗湿红襕，倩郎摇素纨。","云鬟胡乱挽，罗帐金钩捲。","笑掷竹夫人，无端一面嗔。"]},{"t":"菩萨蛮 其十五 月夜","f":"古风","c":["远山新吐蛾眉月，半钩飞入梧桐叶。","刚得照妆台，昵人脱燕钗。","风吹裙带急，花下凭肩立。","细数旧时欢，低头屈指尖。"]},{"t":"菩萨蛮 其十六 冬闺","f":"古风","c":["翠钿尽卸香云绿，红衫松扣纤纤玉。","旖旎揭罗帷，移灯匿笑时。","闭门霜月去，不减春宵味。","炉火酿馀烟，氤氲初睡还。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其十七","f":"古风","c":["曲江芳草年年碧，郎君骑马胭脂色。","白首苦低垂，花间扶杖归。","逢场曾作戏，乔扮参军势。","浓笑写官衔，排行无二三。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其十八","f":"古风","c":["六宫闹扫芙蓉镜，君王偶爱飞蓬鬓。","殿脚惜空同，昭阳天几重。","江南春雨晚，红豆新歌满。","流落杜秋娘，琵琶忆上皇。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其十九","f":"古风","c":["少年悔读高唐赋，片云片雨无寻处。","欲买美人图，吴宫香粉无。","三山青鸟断，萼绿何时见。","夜梦是耶非，玉钗金缕衣。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其二十","f":"古风","c":["平生脱手千金剑，衣鹑马狗今谁盼。","负负复何言，饥来难叩门。","白衣应送酒，凝望终无有。","不见夜飞蝉，山妻剧可怜。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其二十一","f":"古风","c":["关山戎马惊鼙鼓，军书百道征徭苦。","风急雁哀叫，荒田寸草无。","千家闻野哭，鬼火逃亡屋。","叹息返柴庐，当门立吏胥。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其二十二","f":"古风","c":["短衣匹马卢龙道，冰霜千里催人老。","白发影婆娑，秋风鬼病多。","苦寒还苦热，飞梦惊明灭。","何物返魂丹，空囊无一钱。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其二十三","f":"古风","c":["白云冉冉苍梧下，晓猿夜鹤依茅舍。","此地岂蓬壶，梦游疑有无。","一生几两屐，愿作山中客。","只乏买山钱，桃源不在天。"]},{"t":"菩萨蛮 丁巳九月病中有感八首 其二十四","f":"古风","c":["著书自苦徒为尔，千秋万岁谁传此。","前后两茫茫，三生人断肠。","黄金空铸错，彩线难缝络。","何处度余年，除非离恨天。"]},{"t":"菩萨蛮 扬州怀古二首 其二十五","f":"古风","c":["阿嫲曾梦江都好，迷楼一炬空荒草。","何处教吹箫，凄凉廿四桥。","西风吹客舍，落叶隋堤下。","谁唱望江南，惟闻昔昔盐。"]},{"t":"菩萨蛮 扬州怀古二首 其二十六","f":"古风","c":["青楼小杜扬州梦，纱灯万点觥船弄。","书记纵才高，怜才思太牢。","途穷悲逆旅，一饭今谁主。","翠袖薄寒时，却吟老杜诗。"]},{"t":"菩萨蛮 其二十七 佳人集曲名","f":"古风","c":["步摇颗颗珠环小，裙拖滴滴金泥巧。","早起傍妆台，笑兜红绣鞋。","名香罗带染，碧玉钩帘捲。","度曲喜双声，呼郎并合笙。"]},{"t":"北仙吕·一半儿","f":"古风","c":["清和天气晓寒余，客梦江干赋索居，风动琐□绿满除。","漫摊书，一半儿斜阳一半儿雨。"]},{"t":"胡蓝狱","f":"古风","c":["去年杀韩信，今年醢彭越。","徐常幸前死，诸公宁望活？","丞相戮，将军诛，觖望恣肆固有迹，坐以谋反疑有无，罪止及身或收孥。","杀胡党，杀蓝党，数十万人保无枉，文武军民打一网。","一斗粟，一座城，一条龙，一连鹰，革左塌回何纷纷，得非此辈之冤魂！"]},{"t":"煮粥行","f":"七言古诗","c":["去年散米数千人，今年煮粥才数百。","去年领米有完衣，今年啜粥见皮骨。","去年人壮今年老，去年人众今年少。","爷娘饿死葬荒郊，妻儿卖去辽阳道。","小人原有数亩田，前年尽被豪强圈。","身与庄头为客作，里长尚索人丁钱。","庄头水涝家亦苦，驱逐佣工出门户。","今朝有粥且充饥，那得年年靠官府！","商量欲向异方投，携男抱女充车牛。","纵然跋步经千里，恐是逃人不肯收。"]},{"t":"菩萨蛮 秋思回文二首 其二十八","f":"古风","c":["冷霜凝月摇空影，影空摇月凝霜冷。","花落晚窗纱，纱窗晚落花。","断肠人字雁，雁字人肠断。","啼梦晓风西，西风晓梦啼。"]},{"t":"菩萨蛮 秋思回文二首 其二十九","f":"古风","c":["一声啼雁铺沙白，白沙铺雁啼声一。","孤枕夜凉初，初凉夜枕孤。","捣砧和梦悄，悄梦和砧捣。","愁客望高楼，楼高望客愁。"]},{"t":"巫山一段云 其一 贺侯大年新婚","f":"古风","c":["凤婿名萧史，珠娘号丽华。","春风初长合昏花。","门驻碧钿车。","佳话玉如意，新妆香辟邪。","红窗蜡烛小侯家。","臂系汉宫纱。"]},{"t":"巫山一段云 其二 集美人名","f":"古风","c":["紫玉雕歌扇，红绡织舞裙。","年华小小貌真真。","锦字写双文。","花蕊当窗见，兰香隔座闻。","莫愁春信夜来分。","入梦有朝云。"]},{"t":"卜算子 其一 夜忆","f":"古风","c":["秋雨急如筝，弹破江南梦。","野外西风叶叶吹，撼起栖鸦动。","夜永惜灯残，衾薄知寒重。","飞尽征鸿莫寄书，曲冷文君弄。"]},{"t":"卜算子 其二 闺思","f":"古风","c":["整日数归期，数了回头数。","不信朝朝暮暮思，历本看掀破。","特地倚门妆，依旧空床卧。","多分宵来梦不应，今夜拼重做。"]},{"t":"卜算子 其三 忆别","f":"古风","c":["忆别燕双双，新燕添三五。","教妾空房羞独眠，打碎巢边土。","莫更摘花来，且自衔书去。","唤得萧郎早早归，与汝重修补。"]},{"t":"减字木兰花 其一 送春","f":"古风","c":["重门深掩，不道背人归去远。","倦燕娇莺，啼出阳关第四声。","含愁想问，飘泊天涯何处定。","梦断罗帷，今夜明朝睡起迟。"]},{"t":"减字木兰花 其二 春去","f":"楚辞体","c":["春乎欲去，何以赠之双泪雨。","回首东风，一缕飘魂赶落红。","绿兮满树，花影半窗秋色暮。","人倚栏杆，愁听空梁燕语寒。"]},{"t":"减字木兰花 其三 新竹","f":"古风","c":["此君一个，与我周旋林下坐。","新出三竿，官样青袍玉笋班。","萧萧风动，惊破西堂春草梦。","旧箨还裁，好放些儿月影来。"]},{"t":"丑奴儿令 偶感","f":"古风","c":["春来秋去何时了，昨日阴山。","今日阳关。","白发黄鸡弹指间。","只求梦里流年好，今夜邯郸。","明夜巫山。","睡过三生亦喜欢。"]},{"t":"柳含烟 杨柳","f":"古风","c":["青青柳，正藏鸦。","借问风吹多少，霓裳一舞自堪夸。","旧杨家。","可恨销魂桥畔路。","送去征人无数。","却教闺梦变飞花。","向天涯。"]},{"t":"谒金门 其一 愁","f":"古风","c":["奈何许。","欲说近来愁绪。","愁到依然无一语。","罗衫几点雨。","旧事子规催去。","新恨鹧鸪留住。","梦逐东风无歇处。","飘零随柳絮。"]},{"t":"谒金门 其二 寒夜","f":"古风","c":["人寂寂。","一派暮愁天色。","风剪轻寒落渐侧。","纸窗吹半黑。","正对孤灯萧瑟。","又听孤鸿嘹呖。","庭外黄花清露滴。","泪痕依样湿。"]},{"t":"谒金门 其三 代和韦庄","f":"古风","c":["休相忆。","红叶不传消息。","燕锁雕梁路未识。","旧巢难再觅。","风捲杨花无力。","浪打萍花无迹。","永巷夜台同寂寂。","土花凝血碧。"]},{"t":"谒金门 其四 题龚静照鹃红稿","f":"古风","c":["鹃红稿。","静照恰同清照。","最是销魂新句好。","回身将梦抱。","叵耐氤氲颠倒。","彩凤教随乌鸟。","晓镜画眉添懊恼。","红颜祈速老。"]},{"t":"忆秦娥 感春","f":"古风","c":["春来矣。","春风细剪春林绮。","春林绮。","梦随春住，情随春使。","春妆含笑春衫泪。","春光活泼春心死。","春心死。","一番春恨，一番春喜。"]},{"t":"更漏子 其一 独夜","f":"古风","c":["五更风，三点雨。","并作零钟断鼓。","残叶影，落花魂。","凄凄来叩门。","天涯雁，飞声乱。","叫出伤心一片。","倚半枕，拥孤衾。","相思睡不成。"]},{"t":"更漏子 其二 有怀","f":"古风","c":["春风香，秋月弄。","断送十年残梦。","如意曲，定情诗。","相思不自持。","巫山高，湘水远。","惆怅彩鸾缘浅。","霍小玉，董双成。","他生定遇卿。"]},{"t":"清平乐 其一 梅蕊","f":"古风","c":["烟姿玉骨。","淡淡东风色。","勾引春光一半出。","犹带几分羞涩。","陇头倚雪眠霜。","寒肌密抱疏香。","待得罗浮梦破，美人打点新妆。"]},{"t":"清平乐 其二 芦花","f":"古风","c":["秋风泽畔。","小草霜华染。","比似杨花吹不断。","却被雁衔天半。","月明野渡苍茫。","伴他枫叶吴江。","堪笑白头老子，夜寒尚倚红妆。"]},{"t":"清平乐 其三 春闺","f":"古风","c":["懒妆草草。","怕说春光好。","几日伤春吟未了。","一幅乌丝残稿。","昼长午梦初醒。","碧桃花下微行。","闲唤侍儿消遣，小楼偷放风筝。"]},{"t":"阮郎归 旅思","f":"古风","c":["他乡无处不凄其。","晚春人易悲。","杨花飘泊水蛄啼。","高楼忆别离。","宿酒醒，篆烟微。","愁来眉渐低。","满帘风雨断肠时。","一声玉笛吹。"]},{"t":"喜迁莺令 贺李丹壑秋捷时年十六岁","f":"古风","c":["唐学士，李青莲。","公子更翩翩。","荷衣总角赋高轩。","名字报红笺。","曲江宴，樱桃畔。","争看紫骝白面。","嫦娥应遣小婵娟。","花插帽檐边。"]},{"t":"海棠春 其一 晚妆和阮亭韵","f":"古风","c":["更衣斗帐流苏响。","拂舞镜、垂垂丝网。","一片美人云，弄影秋波漾。","小鬟帮衬新兴样。","梳掠罢、口脂相赏。","飞鬓恼春风，莫放罘罳敞。"]},{"t":"海棠春 其二 午睡和韵","f":"古风","c":["氤氲绣幕香生足。","欹山枕、弓腰低曲。","一搦藕肢柔，刚贴芙蓉褥。","梦中辅体靡红肉。","蓦惊起、坠钗寒玉。","笑看抱谁眠，却是夫人竹。"]},{"t":"海棠春 其三 晚浴和韵","f":"古风","c":["画帘双燕争花影。","睡未足、海棠惊醒。","玉骨六铢轻，心怯温泉冷。","起来弄色芙蓉镜。","分外好、髻松鬟整。","无力倚薰笼，呼点龙团饼。"]},{"t":"海棠春 其四 夜坐和韵","f":"古风","c":["井梧叶落声如雨。","又风送、小楼砧杵。","淡月隐屏山，花底闻私语。","空床好梦抛人去。","厮守尽、更更更鼓。","不见谢郎归，烛影摇松尘。"]},{"t":"海棠春 其五 为吴茵次韵寿马少君","f":"古风","c":["沙星畔扶风马。","看绿鬓、白眉相亚。","月里嫁吴刚，桂殿鸳鸯瓦。","娇儿玉雪妆台下。","自句读、焉哉乎也。","生日在豳风，君子歌需雅。"]},{"t":"摊破浣溪沙 其一 春闺","f":"古风","c":["愁倚东风唱踏莎。","画屏十二自腾那，殃及斑鸠天外去，唤哥哥。","无限翠颦低远岫，几番红泪上横波。","却与落花千万点，一般多。"]},{"t":"暮怀寄卿谋","f":"五言古诗","c":["晚云何自横，独照悲秋客。","倒景入林深，烟飞夜光白。","明月当天来，惊起空梁色。","搔首步荒庭，暮影萧然只。","美人西一方，呼之不能出。","我欲化明月，飞到南楼侧。","恐君高枕眠，未敢穿窗入。","惟有草虫声，助予三叹息。","木末赛芙蓉，持赠长相忆。","鸿雁几时来，仰对西风立。"]},{"t":"春寒","f":"七言古诗","c":["雌风盲雨争春国，东皇徘徊不能入。","羯鼓催花花不开，花魂愁抱枯枝泣。","荒烟扰扰萦空飞，冻云寒凝青山白。","落霙斜织夜明帘，兽炉吹断龙涎色。","琉璃砚匣晓冰封，醍醐手怯叵罗执。","西楼美人睡起迟，髻冷芙蓉盘不得。"]},{"t":"秋怀 其一","f":"七言律诗","c":["独倚西楼第一栏，秋风吹绽葛衣寒。","青山几点叶初落，白雁数声星欲残。","镫火草虫人叹息，池塘夜雨梦阑珊。","眼前何限难平事，看了吴钩不敢弹。"]},{"t":"秋怀 其二","f":"七言律诗","c":["一井青山下晚汀，萧萧蒲柳望秋零。","十三楼上人吹笛，五丈原前夜落星。","渔棹绕残深浅渡，雁行排过短长亭。","闲来行乐无余事，删得茶经又酒经。"]},{"t":"由君山入黄山","f":"七言律诗","c":["君山行尽是黄山，山脊中分大石湾。","帆影忽来千树里，江声若出万峰间。","水云自起羁愁合，野鸟高飞客思闲。","临去尚劳回首望，美人日暮绾湘鬟。"]},{"t":"独夜","f":"五言古诗","c":["忧来畏白日，颇喜夜气深。","空梁漏明月，桐风翻秋衾。","静然无所思，思起弹玉琴。","不弹琴中曲，独弹琴中心。","鸣蛩皆有意，能写空山音。","仰观天宇旷，星斗光萧森。","苍烟所聚处，下有阆风岑。","我欲往从之，精神远追寻。","相忘澹如此，谁知世古今。","但恐梦中去，愁境横来侵。"]},{"t":"汪涵夫使君招同张公选范赤生泛舟秦淮感旧有作","f":"七言律诗","c":["一篙春水绿平桥，兰艇相将逐暮潮。","河畔柳枝新系马，渡头桃叶旧吹箫。","六朝金粉愁烟没，二月莺花苦雨消。","凭仗酒樽能壮客，未容问答老渔樵。"]},{"t":"舟中连雨","f":"五言律诗","c":["漏天何日了，高卧尺篷孤。","但听水呜咽，不知山有无。","春心黏柳絮，客梦冷菰蒲。","却羡溪边叟，纶竿入画图。"]},{"t":"至建宁送朱素书往汀州","f":"七言律诗","c":["细雨钱塘共放舟，残镫浊酒几淹留。","日扶短竹穿危岭，夜拥寒衾枕急流。","山鬼路深花窈窕，土人语杂鸟钩辀。","送君更上临汀去，春水平添万里愁。"]},{"t":"客思","f":"七言律诗","c":["梵刹新凉起薜萝，征衣萧瑟问如何。","四山古木弹声急，一夜西风蛩语多。","芳草似啼垂玉露，美人有梦隔银河。","闲将客思题梧叶，翘首天南无雁过。"]},{"t":"邓元昭太史古鼎歌","f":"古风","c":["汉汾阴，得宝鼎。","歊浮云，吐金景。","后作者，何纷纭。","八阵图，五千文。","齐人真，鲁人赝。","千百年，谁能辨。","呜呼孝子有邓公，作庙翼翼宫雍雍。","于豆于登罔不供，若求弗得心忡忡。","天开神物出土中，龙文炳焕琢鬼工。","东西南北云逢逢，是为宝鼎二樽从。","陈之高阁疏布封，以荐彝罍考鼓钟。","考鼓钟，衎宗祖。","奏缓歌，起会舞。","钟山风，摄山雨。","灵连蜷，憺容与，歆尔子孙祚多祜。","我铭斯，大复古，嗟哉邓公正考父。"]},{"t":"送宋牧仲榷使赣州","f":"七言律诗","c":["帝京云物睹阳回，赋别登临宋玉才。","征棹正随寒雁去，放衙应及早梅开。","金娥升处留妆阁，木客吟成乞酒杯。","身在江湖心魏阙，青春还上郁孤台。"]},{"t":"送邵村归维扬子长归吴门","f":"七言律诗","c":["《骊驹》满路送君归，我独临歧赋《式微》。","斜日一鞭随猎骑，大江双桨渡渔矶。","月明隋苑闻箫吹，枫落吴宫看燕飞。","踯躅京华成底事，故乡东望欲沾衣。"]},{"t":"重阳登高","f":"五言律诗","c":["最是高难问，青天隔九重。","亭皋一搔首，风雨满千峰。","野色生新黍，秋声入暮钟。","十年摇落意，泽畔老芙蓉。"]},{"t":"题张德符方瓢册","f":"七言律诗","c":["韩愈高文传李汉，扬雄奇字付侯芭。","谁知江夏先生集，又出清河公子家。","三径松风常放鹤，一帘谷雨自煎茶。","此中图画堪招隐，莫问门前白鼻騧。"]},{"t":"赠高淳吴季舒","f":"七言律诗","c":["江左高人吴季舒，蓬蒿满径闭门居。","十年自著《幽通赋》，四海相传《却聘书》。","淮水观镫名藉甚，隋堤折柳意何如。","风尘澒洞霜华晚，归去淳湖老钓鱼。"]},{"t":"冒辟疆移家诗","f":"七言律诗","c":["西园公子妙谈棋，南国娇娆工扫眉。","云雨凄凉《神女赋》，江山寥落党人碑。","妆楼镫火低鬟影，禅榻茶烟飏鬓丝。","画里浮家风景好，吴宫花发早春时。"]},{"t":"送李子德检讨归养 其一","f":"七言律诗","c":["高卧荆山三十年，朅来待诏赋《甘泉》。","身依北阙君门下，梦绕西京亲舍边。","抗疏遽辞彤管侍，归田仍赐彩衣旋。","闲居频向燕台望，阊阖云深隔九天。"]},{"t":"送李子德检讨归养 其二","f":"七言律诗","c":["都亭把酒送君归，渭水高堂志不违。","筑圃正逢红稻熟，扶筇常看白云飞。","未酬君命臣犹壮，暂解朝班世已稀。","千里莼羹吴地远，自怜乡思欲沾衣。"]},{"t":"送严给谏入都","f":"七言律诗","c":["汉京雅重严夫子，未许桐江把钓竿。","重起千门看橐笔，传闻三省喜弹冠。","天回紫塞龙鳞动，日射青蒲鹿角寒。","又见趋庭真御史，一家骢马满长安。"]},{"t":"摊破浣溪沙 其二 即事","f":"古风","c":["燕子楼中燕子飞。","鹧鸪屏外鹧鸪啼。","笑看萧郎盘细马，画桥西。","鹅管笙囊调艳曲，凤花箫局试香衣。","怪底游人争指道，使君妻。"]},{"t":"眼儿媚 画眉","f":"古风","c":["水晶帘下看梳头。","宛转小眉修。","自然宫样，远山欲笑，新月如钩。","绛仙何用供螺黛，淡扫恰风流。","张郎多事，横添一笔，带出闲愁。"]},{"t":"三字令 雁字","f":"古风","c":["紫塞雁，望南飞。","写乌丝。","一画破。","八分齐。","鹤衔书，鹅换帖，不如伊。","征戍客，寄相思。","却无题。","荡子妇，夜眠迟。","惊回头，仿佛见，那人儿。"]},{"t":"少年游 离情","f":"古风","c":["长亭回首暮云遮。","今夜宿谁家。","马上晓风，渡头残月，催送到天涯。","小眉不画鬓儿斜。","镇日背菱花。","记得当时，手斟杯酒，阁泪拨琵琶。"]},{"t":"西江月 其一 桂花","f":"古风","c":["金母团成金粟，天妃散乱天花。","王孙山里大排衙。","不许兰称王者。","分付吴刚休斫，偷香有个虾蟆。","此身已坐广寒家。","仰叫素娥飞下。"]},{"t":"西江月 其二 新嫁娘","f":"古风","c":["月下云翘卸早，灯前罗帐眠迟。","今宵犹是女孩儿。","明日居然娘子。","小婢偷翻翠被，新郎初试蛾眉。","最怜妆罢见人时。","尽道一声恭喜。"]},{"t":"西江月 其三 春恨","f":"古风","c":["燕子不归绣户，画帘空锁斜阳。","春风吹梦到池塘。","芳草对人惆怅。","杨柳挂愁百尺，杜鹃啼泪千行。","晚来特地倚纱窗。","为问落花无恙。"]},{"t":"西江月 其四 自惊","f":"古风","c":["意气纷纷斗蚁，功名恋恋游蜂。","道人打彻五更钟。","惊醒十年噩梦。","心事半销秋雨，鬓丝难系春风。","今来古往夕阳红。","牛背笛声三弄。"]},{"t":"西江月 梅村作物幻八诗颇极巧妙予谓其近于词为小调足之，茧虎 其五","f":"古风","c":["五道蚕丛初辟，三盆虎圈俄修。","采桑秦女自风流。","翻学下车冯妇。","浴罢恰如得子，缫成便可封侯。","彩丝束缚挂钗头。","傍向盘龙欲斗。"]},{"t":"西江月 其六 茄牛","f":"古风","c":["小菜放于牧野，太牢起自田家。","樊迟老圃大开衙。","演出伯牛司马。","入瓮莫愁觳觫，着鞭却喜丫叉。","儿童牵线笑喧哗。","唱道夕阳来下。"]},{"t":"西江月 其七 鲞鹤","f":"古风","c":["闻说枯鱼欲泣，何为化鹤来归。","霓裳玉佩自清辉。","入肆终惭形秽。","北海已成速柘，南山几见高飞。","鲲鹏变化是耶非。","小作逍遥游戏。"]},{"t":"西江月 其八 蝉猴","f":"古风","c":["齐女一朝怨死，王孙再世嬉游。","三声哀叫断肠秋。","却恨当年无口。","跳掷不忧螳臂，沸羹早兆羊头。","从来蝉冕拜通候。","问是沐猴冠否。"]},{"t":"西江月 其九 芦笔","f":"古风","c":["书带草生笔冢，墨池人在芦中。","白头翁变黑头公。","夜夜飞花入梦。","画荻教成孺子，编蒲学近儒宗。","雁行衔去向江东。","写出锦书珍重。"]},{"t":"西江月 其十 橘灯","f":"古风","c":["金颗千头火树，玉荷四照霜花。","书生怀袖向窗纱。","长伴红衣不夜。","心事任教分剖，风光尚费周遮。","美人对影暗嗟呀。","决意为郎吹罢。"]},{"t":"西江月 其十一 核桃船","f":"古风","c":["种自玄都道士，载从渡口渔翁。","小儿偷出碧云宫。","顷刻帆樯飞动。","芦苇似来江上，竹枝疑泛图中。","桃根桃叶棹歌同。","两桨春风吹送。"]},{"t":"西江月 其十二 莲蓬人","f":"古风","c":["妾比芙蓉解语，郎如碧藕多思。","个人憔悴倒悬时。","知道无心怜子。","空洞此中无物，崛起犹昔孤支。","乱头粗服貌如斯。","未必六郎相似。"]},{"t":"南柯子 其一 懒懒和卿谋韵","f":"古风","c":["侍女休催绣，才郎莫画眉。","春来常倩梦追随。","只为罗衣、不耐晓风吹。","垂手嫌红袖，凭肩恋锦帷。","生憎花影学人窥。","央得鹦哥、传语却忘谁。"]},{"t":"南柯子 其二 旅中苦雨","f":"古风","c":["土雨埋荒草，金风剪败荷。","行人滑滑奈泥何。","不道梦魂、夜夜渡滹沱。","遣兴搜书里，关愁伴枕窝。","孤衾早怯晓寒多。","试问江南、小阁尚轻罗。"]},{"t":"醉花阴 其一 闺病","f":"古风","c":["海棠夜向西风哭。","瘦损枝头玉。","秋雨冷啼妆，半枕红痕，泪染罗裙绿。","药烟细袅湘帘曲。","镜掩芙蓉褥。","闲杀画眉人，懊恼文君，倒犯相如狱。"]},{"t":"醉花阴 其二 寒食","f":"古风","c":["春光百五浑依旧。","细雨宵来凑。","未到落红时，默默东风，已向桃花咒。","江城客居孤单候。","白日清寒透。","天意也销魂，捲尽疏烟，禁得垂杨瘦。"]},{"t":"双调望江南 其一 西山烧香曲","f":"古风","c":["清早起，天色趁新晴。","飞鬓斜拖双燕翠，画衣薄衬小鸦青。","素裹玉丁丁。","回镜照，时样称人情。","多分拼教游子看，私先殃及侍儿评。","公论是轻盈。"]},{"t":"双调望江南 其二 西山烧香曲","f":"古风","c":["呼女伴，好趁一春闲。","红板浪船行缓缓，白藤山轿坐端端。","低扇避人看。","拜佛罢，本意不相关。","戏买粉孩敲木棒，强分叶子赌金环。","图得大家顽。"]},{"t":"杏花天 旅思","f":"古风","c":["消磨白日浑无计。","算只有短眠长睡。","归梦做来千万次。","纸上重重牢记。","相思样子都相类。","换不出思乡新意。","悬知闺梦多佳事。","得个书儿题寄。"]},{"t":"浪淘沙 其一 楼上愁和卿谋韵","f":"古风","c":["赢得许多愁。","岁月悠悠。","秋风秋雨冷双眸。","欲赠湘君搴杜若。","难问芳洲。","长啸倚南楼。","霜鬓飕飕。","栏杆拍遍把吴钩。","惆怅归来无个事，又上灯篝。"]},{"t":"浪淘沙 其二 楼上愁和卿谋韵","f":"古风","c":["回首仲宣楼。","浩浩江流。","楚云湘雨几家收。","画角西风声一片，烽火神州。","准拟泛新愁。","一叶扁舟。","珠帘捲尽雁行秋。","无赖梦魂飞不定，何处相留。"]},{"t":"浪淘沙 其三 咏昭君套","f":"古风","c":["一握小丁貂。","艳色茸毛。","金珰满座总粗豪。","妆向美人头上去，别样妖娆。","双尾鬓云交。","秀映眉梢。","若教上马更多娇。","从此香闺添小字，唤作昭昭。"]},{"t":"浪淘沙 其四 感旧","f":"古风","c":["故旧半凋残。","满目青山。","姓名恍惚古人看。","追忆平生都似梦，今日魂还。","老去鬓毛斑。","努力加餐。","百年应作六如观。","世事浮云君莫管，还我渔竿。"]},{"t":"浪淘沙 其五 题刘六皆桃源图","f":"古风","c":["红树满青山。","涧水潺潺。","烟霞无恙洞门关。","前度刘郎今又至，绿鬓微斑。","花下倚双鬟。","一笑追欢。","胡麻屑饭劝加餐。","莫学淮南天上去，鸡犬云间。"]},{"t":"鹧鸪天 其一 和叶小鸾梦中作","f":"古风","c":["口咏金经手采香。","自言自笑自相忘。","云游瑶碧三山远，舟戏珊瑚一水长。","花筑榭，树回廊。","闲持藜杖逐流光。","何人松下敲棋坐，子落丁丁犹费忙。"]},{"t":"鹧鸪天 其二 题吴冰仙画","f":"古风","c":["拂水佳人堕马妆。","春来响屧满横塘。","绣襦甲帐无消息，暮雨潇潇空断肠。","笔翡翠，砚鸳鸯。","吴绫三尺写红窗。","青山碧水无人处，乱点桃花赚阮郎。"]},{"t":"河传 戏拟闺中十二月乐词 其一 正月","f":"古风","c":["新年吉利。","华胜妆钗，宜春贴字。","檀郎把酒，屠苏索醉。","道儿家得岁。","闹蛾满路鳌山会。","猜灯谜。","输了鸳鸯翠。","却拉邻家姊妹。","紫姑相伴戏。"]},{"t":"河传 其二 二月","f":"古风","c":["春半社来飞燕。","丽日花朝。","茜裙扑蝶过红桥。","垂腰折柳条。","汉宫寒食新传火。","贻雕卵。","耍笑郎家果。","墙头马上看秋千。","喧阗。","争分白打钱。"]},{"t":"河传 其三 三月","f":"古风","c":["春午红雨。","湔裙曲水，采兰江渚。","万花舆。","百子襦。","伴侣。","踏青芳草舞。","拾来斗合鸳鸯谱。","瑶环赌。","赢取同心缕。","晚还家。","倚碧纱。","周遮。","金铃偷护花。"]},{"t":"河传 其四 四月","f":"古风","c":["红英已谢。","绿枝方亚。","拂拂薰风。","一番谷雨，晓来香透帘栊。","鼠姑红。","罗敷日日条桑下。","缫丝罢。","梅润罗裙钗。","小窗闲处，提壶自试新茶。","换轻纱。"]},{"t":"河传 其五 五月","f":"古风","c":["佳辰重午。","钗悬艾虎。","臂缠彩缕。","龙舟两两竞渡。","画鼓。","雕弓射角黍。","兰汤浴罢蒲觞泛。","红生面。","窈窕摇葵扇。","凭栏杆。","亸髻鬟。","阑珊。","乞郎半夏丸。"]},{"t":"河传 其六 六月","f":"古风","c":["玉骨冰肌，天然无汗。","纨素风来，鬘华香散。","小池边。","棹船歌采莲。","昼长独抱青奴卧。","桐阴破，枕畔金钗堕。","起看明月上纱窗。","萧郎。","桃笙今夜凉。"]},{"t":"河传 其七 七月","f":"古风","c":["高楼乞巧。","綵花飞起，云霞缭绕。","金钿七孔试穿针，袅袅。","穿出双头巧。","戏呼乌鹊填河去。","凌波步。","便唤郎来渡。","渡来时。","赴佳期。","水嬉。","银盆弄化儿。"]},{"t":"河传 其八 八月","f":"古风","c":["琼楼玉宇。","紫云霓羽。","广寒何处。","有人问月府。","白衣歌舞。","是嫦娥小女。","月圆正值人圆夜。","箫楼下。","彩凤应同跨。","泛金卮，弹锦丝。","红儿。","为郎折桂枝。"]},{"t":"河传 其九 九月","f":"古风","c":["重九。","酌酒。","茱萸遍插，频开笑口。","小楼帘捲也登高。","相邀。","同餐小鹿糕。","自怜人比黄花瘦。","垂罗袖。","瑞脑薰金兽。","背罘罳。","步庭墀。","秋思。","题诗梧叶儿。"]},{"t":"河传 其十 十月","f":"古风","c":["春小。","暖早。","鹦哥报道。","海棠开了。","妆台乍晓。","云髻新添通草。","画衣飞翠鸟。","琐窗容易斜阳下。","香奁卸。","无计消长夜。","剪金凫。","倒玉壶。","胡庐。","偷窥秘戏图。"]},{"t":"河传 其十一 十一月","f":"古风","c":["冬至。","亚岁。","日初长。","八尺花间细量。","新添宫线绣鸳鸯。","尊章。","檠将履袜双。","六出花飞风絮起。","毡炉底。","瑞炭煎沉水。","饮羊羔。","弹凤槽。","蛮腰。","何妨夜夜娇。"]},{"t":"河传 其十二 十二月","f":"古风","c":["岁暮。","腊鼓。","悬螺画虎。","爆竹争喧，藏钩戏赌。","女伴馈节如何。","口脂翠管多。","黄金泻水成双凤。","梅妃弄。","拟献椒花颂。","向围炉劝酒，妾意与郎同。","火儿红。"]},{"t":"河传 其十三 旅思","f":"古风","c":["川犬。","民眼。","凄凄孤馆。","悠悠日晚，醒来谁伴。","只剩残书败卷。","昼长嫌梦短。","天涯怅望云中树。","江南路。","点点疏星吐。","何不归。","何日归。","相催。","春风叫子规。"]},{"t":"鹊桥仙 其一 七夕","f":"古风","c":["玉钩画烛。","金风箫鼓，迎送鹊桥云雨。","鸳鸯债欠许多时，着意在、今宵赔补。","才郎乞巧，佳人穿缕，痴绝不知甘苦。","夜深宛颈睡双浓，那听得、人间私语。"]},{"t":"鹊桥仙 其二 佳人","f":"古风","c":["月眉星眼，烟鬟雾髻，浑是一天妆束。","尤云殢雨更风流，甘折却、人间庸福。","莺莺燕燕，红红翠翠，删尽侍儿名录。","鸳鸯谱样总平常，新翻出、怜欢题目。"]},{"t":"鹊桥仙 其三 落花","f":"古风","c":["乍晴乍雨，乍寒乍暖，做作几般天气。","个人犹自不禁持，何计教、花魂回避。","正青芳草，未衰杨柳，只短夭桃年纪。","落红万点总无情，赚多少、香闺清泪。"]},{"t":"南乡子 其一 春愁","f":"古风","c":["红雨晓阑珊。","寂寞梨花泪未干。","飞絮满庭人倦起，偷怜。","尽日鹦哥话夜寒。","巫峡梦云单。","懊恼春光一半残。","索性闭门推却去，孤眠。","独让东风自倚栏。"]},{"t":"南乡子 其二 病集药名","f":"古风","c":["弱骨怯天冬。","满地黄花憔悴同。","云母屏边休伫立。","防风。","乌头却似白头翁。","自笑寄生穷。","愁脉难将草木通。","泉石膏肓甘遂老，从容。","领取云山药饵功。"]},{"t":"南乡子 其三 闺中除夕","f":"古风","c":["榾柮暖炉烟。","笑劝屠苏称合欢。","自爇沉檀供绣佛，低言。","愿妾红颜胜旧年。","隔夜整钗钿。","守着梅花不去眠。","更有一椿郎谶取，团圆。","预乞明朝拜节钱。"]},{"t":"南乡子 其四 闺中元旦","f":"古风","c":["灯下了妆奁。","玳瑁堂前春色添。","万福归来无一事，憨憨。","自揭薰笼换绣衫。","迎喜出门檐。","笑看家家下竹帘。","瓜子满阶人莫扫，纤纤。","曾带脂香唾舌尖。"]},{"t":"南乡子 其五 吊邹氏废园","f":"古风","c":["华屋委荒丘。","萧瑟西风十二楼。","留下空梁巢燕，啾啾。","梦忆珠帘碧玉钩。","歌舞彩云流。","野草斜阳伴客愁。","惟有青山依旧在，悠悠。","看尽红颜又白头。"]},{"t":"南乡子 其六 席上戏赠女伶文玉","f":"古风","c":["珠箔舞蛮靴。","浅立氍歈宛转歌。","忽换猩袍红烛艳，瞧科。","锦伞将军小黛蛾。","鬒发尚盘螺。","一瓣丝鞭燕尾拖。","为待情人亲解取，谁何。","春草江南细马驮。"]},{"t":"虞美人 其一 怜病","f":"古风","c":["病魔才别书帷去。","又借香奁住。","恹恹瘦骨怯春纱。","犹向药烟影里问残花。","晓来强起妆台立。","揽镜愁眉窄。","侍儿且罢掠云鬟。","恐怕春风多厉不胜寒。"]},{"t":"虞美人 其二 虞美人花","f":"楚辞体","c":["重华昔向苍梧死。","羽亦重瞳子。","至今舞草号虞兮。","可似黄陵斑竹泣湘妃。","君王莫恨江东小。","暖日花光好。","开时常对杜鹃红。","一样暗伤亡国月明中。"]},{"t":"虞美人 其三 石榴花","f":"古风","c":["李家妹子陶家姊。","甘逐封姨死。","石家房老剩翾风。","好把小名醋醋换红红。","艳妆底事心如火。","生日逢重午。","萧郎笑插玉人头。","问道留侬侬去若为留。"]},{"t":"虞美人 其四 思归","f":"古风","c":["官街听彻三更鼓。","缩脚寒衾苦。","无眠终夜眼常开。","那得巫山湘水梦魂来。","隔江望断家乡路。","小雪冬垂暮。","扁舟归去未嫌迟。","正是纸窗炉火芋香时。"]},{"t":"玉楼春 其一 为黄大宗悼亡郭少君","f":"七言律诗","c":["柔肠最怕伤心赋。","听说埋香泪便堕。","红颜惯是误青春，断送桃花一夜雨。","飞琼携手瑶台路。","应驾钿车游戏去。","可堪抛向玉钩斜，梦散彩云无觅处。"]},{"t":"玉楼春 其二 为黄大宗悼亡郭少君","f":"七言律诗","c":["落花急似三更漏。","弱质盈盈才十九。","杜鹃哭杀少年坟，小字彤碑碧血绣。","萧郎梦断蘼芜后。","宝镜鸳鸯难再偶。","可怜薄命玉容人，值得挽歌三十首。"]},{"t":"梅花引 晓行","f":"古风","c":["晓星稀。","晓风低。","晓月如霜冷射衣。","晓鸡啼。","晓鸡啼。","啼上征鞍，朦胧古道西。","水声呜咽行人泪。","雁声嘹呖归人字。","影凄其。","影凄其。","斑马频嘶，前村望酒旗。"]},{"t":"踏莎行 其一 闺怨","f":"古风","c":["独上妆楼，青山如昨。","画眉彩笔春来阁。","休弹红雨湿花梢，泪珠自向心头落。","可恨东风，年年轻薄。","天涯不管人漂泊。","漫将薄幸比杨花，杨花犹解穿罗幕。"]},{"t":"踏莎行 其二 题周宝蹬坐月浣花图","f":"古风","c":["坐月青莲，浣花工部。","闺房之秀兼佳趣。","燃脂写出丽人行，风鬟雨髻姗姗步。","碧杜红兰，明珠翠羽。","药房移傍湘君住。","可怜荡子不归家，长吟荡妇秋思赋。"]},{"t":"踏莎行 其三 题周宝蹬坐月浣花图","f":"古风","c":["放诞文君，风流樊素。","殢人更在仓庚妒。","武昌新柳自青青，生憎隔岸晴川树。","欢晕红凝，愁眉绿聚。","幽情难向狂夫诉。","莫携此卷渡江来，津头有个兴风雨。"]},{"t":"踏莎行 其四 客店","f":"古风","c":["残月在林，晨钟动野。","行人惯听乌啼夜。","一鞭古道又斜阳，村田看尽羊牛下。","草席泥床，瓦盆茅舍。","东餐西宿何时罢。","孤灯半枕梦江南，隔帘惊起萧萧马。"]},{"t":"小重山 其一 金陵怀古","f":"古风","c":["依旧青山绕建康。","南朝佳丽地、草茫茫。","景阳脂井冷银床。","秦淮月，犹照故宫墙。","吊古石头冈。","大江流日夜、几兴亡。","鸡笼鼠雀满祠堂。","君莫问，策蹇下斜阳。"]},{"t":"小重山 其二 维扬旅思","f":"古风","c":["锦缆牙樯金犊车。","竹西歌吹地、斗繁华。","闲来独吊玉钩斜。","隋宫女，为我诉琵琶。","客梦绕天涯。","江山虽窈窕、不如家。","二分明月广陵花。","一分月，斜照小窗纱。"]},{"t":"临江仙 其一 迎春","f":"古风","c":["昨夜饯冬三寸雪，晓光俄报春回。","绿杨青草媵红梅。","东风齐着力，送入我门来。","箫鼓綵毬迎去也，游人蚁走长街。","珠帘影里笑金钗。","老姬驮瘦马，儿戏唱低牌。"]},{"t":"临江仙 遣兴二首 其二","f":"古风","c":["搔首问天天不语，光阴无计消磨。","挑灯看剑自摩挲。","浇胸冷热酒，拍手短长歌。","遮莫英雄老去也，山林经济如何。","平章重事到烟波。","铙吹传玉鸭，水战教金鹅。"]},{"t":"临江仙 遣兴二首 其三","f":"古风","c":["少日驱车兼跃马，锦裘风雪行边。","十年回首鬓萧然。","蹇驴花下路，短笠渡头船。","凭寄壮心歌舞地，绿樽翠袖红弦。","不然散发事金仙。","蒲团香影里，横槊自参禅。"]},{"t":"临江仙 其四 旧内","f":"古风","c":["六代青山依旧在，霸图吹断西风。","行人驻马问离宫。","游船建业水，旧寺景阳钟。","百战精灵应未散，周郎独步江东。","旌旗夜拥紫髯翁。","漫追亡国恨，又见孝陵松。"]},{"t":"临江仙 其五 旧院","f":"古风","c":["十四楼前歌舞地，珠帘画障神仙。","月明花底弄红弦。","无双桃叶曲，最小莫愁年。","战鼓催残金粉尽，空寻坠舄遗钿。","香销南国忆婵娟。","东风芳草绿，裙带我犹怜。"]},{"t":"临江仙 其六 题汪蛟门锦瑟图","f":"古风","c":["二十四桥佳丽地，砚斋十二平分。","江郎梦笔助奇文。","情深聊尔尔，才妙漫云云。","二十五弦弹夜月，花间锦瑟横陈。","春风鬓影看文君。","一窗三妇艳，谁雨复谁云。"]},{"t":"临江仙 其七 寿查伊璜","f":"古风","c":["丝竹东山自有，烟花南部偏多。","红儿起舞雪儿歌。","人生行乐耳，但日饮亡何。","喑呜叱咤，文章者也之乎。","不如老子兴婆娑。","珠帘披毳衲，玉笛卧渔蓑。"]},{"t":"蝶恋花 其一 悲秋","f":"古风","c":["秋气悲哉秋景肃。","引出秋声，夜到西南哭。","聚族新忧无计逐。","踌躇独去逃深屋。","枫自飘红榆自绿。","蟋蟀莎鸡，争唱凉风曲。","雁阵惊寒音断续。","披衣起写相思牍。"]},{"t":"蝶恋花 其二 书闷","f":"古风","c":["雨雨风风飘曲院。","点点丁丁，滴碎柔肠断。","听说阑珊春又半。","无端惹起伤春怨。","料峭轻寒犹拂面。","况是啼鸠，日向愁人唤。","司马青衫红泪溅。","倚栏惆怅綦巾伴。"]},{"t":"蝶恋花 其三 吊返生香","f":"古风","c":["彤管不随春梦度。","留与人间，啼哭相思句。","一本青编红泪注。","离魂缩入香奁住。","仿佛真真纸上语。","为雨为云，飘渺无凭据。","行到吴江枫落处。","自携一叶归家去。"]},{"t":"蝶恋花 其四 寒夜","f":"古风","c":["铁作衾裯冰作枕。","天意萧条，也学人情冷。","薄酒三杯容易醒。","辘轳万事心头滚。","数尽铜壶玉漏永。","茅舍荒鸡，啼断阳关引。","泪点双眸开炯炯。","纸窗浸破霜花影。"]},{"t":"一剪梅 其一 夜落金钱化","f":"古风","c":["风残月过三生。","风里呈身。","月下归魂。","自怜薄命六铢轻。","憔悴黄裙。","冷落红尘。","家姊妹两般分。","夜合随君。","夜落随君。","春光真不值分文。","虽有钱神。","难买花神。"]},{"t":"一剪梅 其二 花烛词","f":"古风","c":["何物风流白面郎。","粉捏何郎。","香和韩郎。","天教撮合紫云娘。","玉琢萧娘。","锦制苏娘。","翠管催成宫样妆。","山画眉妆。","云想衣妆。","银灯低照合欢床。","弦配琴床。","蒂并花床。"]},{"t":"一剪梅 其三 王氏孪生子同夜成婚用前韵","f":"古风","c":["五綵双缠午未郎。","伯楷王郎。","仲楷王郎。","七香并驾杜韦娘。","大妇珠娘。","小妇琼娘。","一夜春风两面妆。","雪点梅妆。","月照梨妆。","鼓琴鼓瑟喜连床。","坦腹东床。","交臂西床。"]},{"t":"好女儿 其一 佳人","f":"古风","c":["一捻脂红。","百和香浓。","半醉娇声半醒态。","在坐亸鬟云，步摇佩玉，卧曲鞋弓。","斜睇檀郎不语，谁惯汝、漫留侬。","问此处、不留何处去，道朝上秦楼，晚游洛浦，暮宿巫峰。"]},{"t":"好女儿 其二 泥美人","f":"楚辞体","c":["彼美人兮。","半面风姿。","谁向妆台描五色，有顾恺传神，何郎傅粉，张敞休眉。","可惜红颜黄土，立而望、是耶非。","问若个、小名君识否。","是罢舞西施，停歌子夜，不笑褒姬。"]},{"t":"渔家傲 其一 渔父","f":"古风","c":["天下滔滔皆是也。","风波满地江河假。","鼓枻行歌君莫讶。","谁知者。","离骚庄子吾其亚。","一尺莲舟桨打。","绿蓑青笠人如画。","泼剌黄鱼穿柳挂。","收纶罢。","提壶闲共樵夫话。"]},{"t":"渔家傲 其二 春闺","f":"古风","c":["梦锁重楼春信杳。","彩丝偷把花魂钓。","笼内鹦哥没紧要。","频嘶叫。","墙角海棠谁折了。","左右懒妆和闷倒。","上裙蟢子惊人跳。","作怪鸦头扯谎报。","才郎到。","愁眉错对菱花笑。"]},{"t":"渔家傲 其三 题沈关关绣顾茂伦濯足图","f":"古风","c":["我梦吴江烟水皱。","纶竿拟挂垂虹口。","不道逋翁濯足久。","枕且漱。","沧浪一曲天如斗。","深院玉人闲谱绣。","粉香妙写溪山友。","宛转彩丝盘素手。","林下秀。","小名独占毛诗首。"]},{"t":"定风波 纳凉","f":"古风","c":["不着衣衫不扫妆。","天边赵盾逼人忙。","安得芳姿乞作婢。","唤至。","手将团扇扇王郎。","却羡摩诃池上路。","行去。","花梢口吸露珠凉。","携手归来竹簟睡。","枕臂。","玉鱼吐出口脂香。"]},{"t":"苏幕遮 其一 塞上","f":"古风","c":["朔云寒，边月苦。","觱栗西风，吹乱黄沙舞。","夜半雪深三尺许。","毡帐驼峰，倒载琵琶女。","打围来，圈地去。","银管炊烟，茶煮乌羊乳。","蛮府将军穷塞主。","匹马随他，看射南山虎。"]},{"t":"苏幕遮 其二 塞上","f":"古风","c":["塞垣长，寒信早。","画角呜呜，吹破霜天晓。","一阵哀鸿残月小。","梦绕南云，泪湿征衫老。","拄青山，吟白草。","燕雀排衙，公事弹琴了。","又报黄旗前队到。","手板匆匆，走马辽西道。"]},{"t":"苏幕遮 其三 行旅用范希文韵","f":"古风","c":["雪花天，泥滑地。","漠漠同云，压破山头翠。","山接平芜田接水。","望断村烟，只在青天外。","五更愁，千里思。","茅舍孤灯，草草留人睡。","放着枕头没处倚。","角角鸡声，啼出思乡泪。"]},{"t":"苏幕遮 其四 徐石兄卜居徐庄","f":"古风","c":["郑公乡，梅尉市。","安石墩头，王谢争端起。","谁似南州徐孺子。","天付吾庐，预注高人里。","十三经，廿一史。","架屋堆床，啸咏乌皮几。","竹舍茅庐何陋尔。","君子居之，即是名山水。"]},{"t":"怨东风 其一 客思","f":"古风","c":["蒲叶端阳寓。","又看银河渡。","江山何事苦留人，住。","住。","住。","破屋颓垣，古槐荒草，满庭秋雨。","泥滑长安路。","马首无停处。","一鞭落日又西风，去。","去。","去。","茅店孤灯，故乡回首，梦中云树。"]},{"t":"怨东风 其二 旅闷","f":"古风","c":["秋暑蝇成阵。","西日长如闰。","无聊所事不宜人，闷。","闷。","闷。","薄酒初醒，孤灯半灭，残书独枕。","愁缕萦方寸。","华发添双鬓。","无端读史更悲歌，恨。","恨。","恨。","剑废荆轲，骓忘项羽，弓藏韩信。"]},{"t":"风中柳 其一 和孙夫人韵","f":"古风","c":["郎上长安，怎好说些烦恼。","但叮咛、马蹄芳草。","自来月下，把泪痕偷告。","梦儿中、教郎知道。","一纸家书，不觉低鬟微笑。","报平安、归期尚杳。","金钗翠凤，送香车须早。","怕春去、燕残莺老。"]},{"t":"风中柳 其二 题沈耕道东轩","f":"古风","c":["枫落吴江，一望烟波凝绿。","问东轩、谁家茅屋。","南窗丛菊。","北窗修竹。","倚胡床、酒香茶热。","渔夫相逢，应许菰芦借宿。","扣舷歌、离骚一曲。","烽烟满目。","荆榛满足。","任澜翻、长安棋局。"]},{"t":"行香子 其一 春暮","f":"古风","c":["紫陌金车。","绿浦兰槎。","共追寻、大地芳华。","三分春色，分与谁家。","有一分山，一分水，一分花。","雨打檐牙。","月落窗纱。","恨韶光、转盼天涯。","小庭寂寞，底事争哗。","是一声莺，一声燕，一声鸦。"]},{"t":"行香子 其二 小园漫兴","f":"古风","c":["一个敦丘。","一个泥沟。","小经营、水尾山头。","烟霞旧管，草木新收。","有杏花春，荷花夏，菊花秋。","万里封侯。","四海登楼。","问何如、樵斧渔钩。","主人高卧，有客来游。","是酒刘伶，诗李白，梦庄周。"]},{"t":"青玉案 无聊","f":"古风","c":["江城萧索愁如此。","门无客、床无史。","歌舞无人能作伎。","无花无酒，无山无水，大抵皆无耳。","旅人却喜闲无事。","只有梦来长伴尔。","梦醒空题诗一纸。","不如归去，纵然寂寞，万事看家里。"]},{"t":"江城子 清明旅思","f":"古风","c":["江城佳节也清明。","喜新晴。","午风轻。","寡柳孤桃妆点可怜生。","罗袜绣鞋人不见，空辜负，满堤青。","客游随分踏莎行。","冷旗亭。","隔花屏。","无限家山绿水画船横。","宝马云麾香过处，看玉手，拨银筝。"]},{"t":"千秋岁 其一 感旧用少游韵","f":"古风","c":["落花帘外。","点点残红退。","云穗乱，风筝碎。","愁拈翡翠管，恨拆鸳鸯带。","薄幸煞，燕儿难捉鹦哥对。","梦想瑶台会，绣被同舟盖。","锦字杳，遗香在。","星移银汉断，雨散巫峰改。","魂去也，化成精卫填青海。"]},{"t":"千秋岁 其二 午日祝江明府","f":"古风","c":["文通能赋。","梦笔如风雨。","采杜若，潇湘浦。","驱车越峤远，岸帻吴山暮。","衙放了，锦帆花月迎明府。","佳节逢端午。","胜事传三楚。","系彩线，穿菰黍。","寿杯菖叶酒，乐语离骚句。","讴歌者，芙蓉江上喧龙鼓。"]},{"t":"千秋岁 其三 寿何湘来","f":"古风","c":["深衣革履。","道貌如秋水。","挥玉麈，依香儿。","心空四句偈，目击三爻理。","蒲团上，卧游五岳华胥睡。","今日长筵会。","戏彩高堂喜。","萼绿舞，飞琼吹。","洪崖酌鹤顶，黄石羞麟髓。","谨谢客，先生笑饮茶而已。"]},{"t":"千秋岁 其四 寿徐太夫人","f":"古风","c":["人间天上。","富贵真无量。","三鼎甲，同驴唱。","五花封邑诰，九节延年杖。","称万寿，鸾台凤阁新官样。","满屋黄金榜。","满座青绫障。","藻绶舞，翚衣飏。","儿觞浮玉酒，妇馈连珠酱。","福备矣，蓬莱王母犹谦让。"]},{"t":"风入松 寒鸦","f":"古风","c":["呀呀掠尽碧天寒。","墨影满青山。","太和门外常相见，乌衣队争点朝班。","应笑西风哀雁，衔芦辛苦榆关。","槎枒枯树倦飞还。","一幅画图间。","谁怜羁旅金闺客，乌啼夜、归思阑珊。","借问几时头白，早看改了朱颜。"]},{"t":"祝英台近 忆别用稼轩晚春韵","f":"古风","c":["玉炉残，银烛暗，画楫维南浦。","黯淡东风，早洒泪痕雨。","恼他顺水船儿，几株杨柳，甚力把、征帆拴住。","空相觑。","欲将心事叮咛，题多总难数。","独夜思量，记起枕边语。","算来万种春愁，妾担不起，分一半、与郎随去。"]},{"t":"一丛花 游朱氏园亭","f":"古风","c":["江村踏踏半平沙。","木槿缚篱笆。","谁引刘郎来洞口，隔墙见、人面桃花。","数曲栏杆，几条书画，也算小山家。","主人白发话烟霞。","虚阁倚风斜。","池边指点平安竹，谷雨近、芍药抽芽。","新出笋尖，旧藏桂子，撮合点新茶。"]},{"t":"金人捧露盘 卢龙怀古","f":"古风","c":["出神京，临绝塞，是卢龙。","想榆关、血战英雄。","南山射虎，将军霹雳吼雕弓。","大旗落日，鸣笳起、万马秋风。","问当年，人安在，流水咽，古城空。","看雨抛、金锁苔红。","健儿白发，闲驱黄雀野田中。","参军岸帻，戍楼上、独数飞鸿。"]},{"t":"最高楼 漫兴","f":"古风","c":["抛官去，乞得小山居。","偃仰此生馀。","何用食为十斛麦，未之学也五车书。","时还读，亦已种，则何如。","待讨个、渔童名便了。","再配个、樵青名大好。","赛赤脚，胜长须。","奴更养奴千树橘，婢还钓婢百头鱼。","挈山妻，同稚子，且相于。"]},{"t":"蓦山溪 夏兴","f":"古风","c":["登楼极目，又见斜阳下。","远近两三峰，一点点、翠眉如画。","莺簧蝉鼓，杨柳舞轻风，人闲暇。","天潇洒。","惆怅如何夜。","白衣苍狗，阅尽云真假。","今古总悠悠，叹举世、尘埃野马。","青天难问，搔首且归来，沉醉也。","高眠罢。","月上葡萄架。"]},{"t":"意难忘 元宵","f":"古风","c":["春色佳哉。","报吴宫花柳，羯鼓方催。","羽林千骑去，华屋万家回。","罗帐地，锦衣街。","灯火上楼台。","看满城、星桥高揭，火树丛开。","月明车马如雷。","有舞旋鲍老，歌打洪崖。","香尘移画舄，玉烛袅金钗。","帘幌下，影徘徊。","听笑语诙谐。","百忙里、阄成灯谜，掷与郎猜。"]},{"t":"满江红 其一 偶览稗史载王文成梦郭景纯极言王导之奸反导阴主之也因为赋此","f":"古风","c":["好个夷吾，渡江后、久窥神器。","谁更念、神州未复，江河顿异。","堪笑一生苏武节，曾无半点新亭泪。","问乱臣、贼子出臣家，谁之罪。","王与马，久分据。","敦与导，还同计。","算败终为相，成当为帝。","漫惜伯仁由我死，太真拔舌斯何意。","叹谁将、赵盾弑君看，书其事。"]},{"t":"满江红 其二 感遇","f":"古风","c":["我醉欲眠，且收了、眼光青白。","分付与、死便埋我，陶家之侧。","天下山川吞八九，腹中人物容千百。","任诸君、拍手笑狂生，乾坤窄。","破面鬼，焦头客。","乌帽吏，黄巾贼。","问何人请剑，何人投笔。","我梦化为蝴蝶舞，醒来敲碎珊瑚缺。","叹一腔、热血洒何时，青衫湿。"]},{"t":"满江红 其三 生日自题小影","f":"古风","c":["铸错难成，空赢得、头颅如许。","君不见、此中有鬼，英雄无主。","世事梦回关塞月，文章泪尽潇湘雨。","叹茫茫、宇宙此身多，无归处。","山岩里，聊容与。","竹林下，方延伫。","但看他白眼，科头箕踞。","背后好遮王导扇，手中只少渔阳鼓。","携一杯、自祝画图前，魂相语。"]},{"t":"满江红 其四 生日自题小影","f":"古风","c":["甚矣吾衰，谁画出、秋风蒲柳。","须信道、相君之面，不过村叟。","车盖鼓吹今梦觉，空山晏坐搔童首。","问何人、不着鵔鸃冠，惟君否。","且避暑，频挥手。","谨谢客，休开口。","只先生生日，归而谋妇。","半臂才更一斗面，百钱恰买三升酒。","对此君、烂醉仰天眠，看苍狗。"]},{"t":"满江红 其五 思隐","f":"古风","c":["寄语青山，为我筑、数椽茅舍。","更计较、凿斯池也，衡门之下。","屋后十弓放笋竹，墙边五亩栽桑柘。","还留些、隙地种梅花，依台榭。","北海钓，南山射。","东墅弈，西园画。","有邻翁来往，鸡豚春社。","笑问老妻能去否，蒿簪藜杖归休罢。","但囊中、尚乏买山钱，从天借。"]},{"t":"满江红 其六 思隐","f":"古风","c":["衮衮诸公，看朱紫、白头随驾。","尽让与、蝇头蜗角，冷杯残炙。","夫子漫劳冉有仆，小人请学樊迟稼。","向深山、好作古田家，羲皇话。","松菊径，瓜藤架。","麋鹿柴，鱼虾汊。","且醉吟高卧，及时闲暇。","稚子浪寻青草斗，老夫合受黄鹂骂。","倘城中、有客访吾来，关门谢。"]},{"t":"满江红 其七 上巳旅思","f":"古风","c":["天朗风和，是昔日、兰亭春社。","恨不见、一时名士，乌衣王谢。","光禄文章曲水宴，子山马槊华林射。","到吾徒、意气向谁人，都休罢。","四海事，归耕稼。","五岳志，销婚嫁。","但短衣长铗，栖迟傅舍。","醉去行歌城阙上，醒来坐啸墙篱下。","听大江、滚滚客心悲，流日夜。"]},{"t":"满江红 其八 余淡心初度和梅村韵","f":"古风","c":["对酒当歌，君休说、麒麟图画。","行乐耳、柳枝竹叶，风亭月榭。","满目山川汾水雁，半头霜雪燕台马。","问何如、变姓隐吴门，吹箫者。","兰亭褉，香山社。","桐江钓，华林射。","更平章花案，秤量诗价。","作史漫嗤牛马走，咏怀却喜渔樵话。","看孟广、把盏与眉齐，皋桥下。"]},{"t":"满江红 其九 倦游初归顾庵绎堂处实既庭枉集草堂用顾庵原韵","f":"古风","c":["梅雨廉纤，问昨夜、小池微涨。","漫一笑、征衫乍脱，故园无恙。","翠箨移来石径侧，黄鹂啼到桐阴上。","更村村、烟火起农歌，田家饷。","报有客，扁舟漾。","看满座，兰亭唱。","喜酒徒相对，欲倾家酿。","却暑但挥蝉雀扇，登高请进蒲桃杖。","向西山、指点夏云生，多奇状。"]},{"t":"满江红 其十 即席赠顾庵学士","f":"古风","c":["二十年来，叹世事、尘霾波涨。","喜老友、跳归燕市，须眉无恙。","皂帽幸辞辽海外，青衫还泣浔江上。","问榜门、谁是脱骖人，千金饷。","且上下，随流漾。","予解和，公能唱。","须浇开磈垒，洞庭春酿。","屈指明年将半百，看云取次从藜杖。","又何老、呵壁续离骚，笺天状。"]},{"t":"满江红 其十一 即席送绎堂宪副北上并寓都中同好","f":"古风","c":["才子仙人，坐春水、泖湖新涨。","从此去、黄河千里，布帆无恙。","玉殿传胪原日下，金门待诏还天上。","料至尊、早办大官厨，为卿饷。","斜日下，雕旗漾。","芳草路，骊歌唱。","送关山牙棨，一樽清酿。","使客自骑沙苑马，野人独倚柴门杖。","倘诸公、闻讯仆何如，穷愁状。"]},{"t":"满江红 其十二 飞涛祠部辞疾不至柬以讯之","f":"古风","c":["太息丁生，出塞去、雪堆沙涨。","谢弋者、辽东归鹤，令威无恙。","浪迹偶来皋庑下，端忧却据胡床上。","正提壶、卢橘满林黄，堪分饷。","端午后，蒲葵漾。","麦秋至，蝼蛄唱。","君奚为高卧，欲逃村酿。","游子渡江不用楫，健儿跃马宁须杖。","剧何堪、新妇闭帷中，婆娑状。"]},{"t":"满江红 其十三 忆别阮亭仪部兼怀西樵考功湖上","f":"古风","c":["我发芜城，趁竞渡、一江风涨。","为寄语、池塘春草，阿连无恙。","白舫已乘东冶下，青骢尚跃西泠上。","问钱塘、可接广陵潮，双鱼饷。","采莲棹，湖心漾。","折柳曲，桥头唱。","办十千兑酒，余杭新酿。","王子正招缑岭鹤，孙登也策苏门杖。","待归来、赠我两峰图，空漾状。"]},{"t":"满江红 其十四 寄呈荔裳观察","f":"古风","c":["北望卢龙，痛精卫、魂填溟涨。","何幸得、南楼老子，下官无恙。","千里相思风雨夕，十年重过江湖上。","笑故人、只有一杯莼，为君饷。","飞蝶梦，游丝漾。","骑马地，朝鸡唱。","算半生白发，星星愁酿。","笠泽烟波宜载酒，泰山日观聊携杖。","再休提、宋玉赋秋风，悲哉状。"]},{"t":"满江红 其十五 苦雨书闷","f":"古风","c":["积雨东篱，雷隐隐、水云时涨。","休夏好、绳床药臼，消磨微恙。","读史喜观秦楚际，咏怀高话羲皇上。","笑饥来、驱我走天涯，无人饷。","愁何许，悬旌漾。","悲未已，吹篪唱。","怪众人皆醉，覆杯沉酿。","堪破黄梁道士枕，打开白业瞿◇杖。","咄何来、修竹弹甘蔗，纷投状。"]},{"t":"满江红 顾庵复和八首见示赋此答之并贻既庭 其十六","f":"古风","c":["何物文心，笔阵老、墨池飞涨。","贾馀勇、吟成八咏，撚髭无恙。","公子七哀传邺下，大夫九辨赓江上。","惊从而和者曲弥高，三缣饷。","倒词峡，真潢漾。","短歌阕，长歌唱。","只江郎才尽，渴求杯酿。","我倦欲投斑竹管，公豪任夺青藜杖。","问红笺、填得许多愁，难于状。"]},{"t":"满江红 其十七 春夜集淡心斋和韵","f":"古风","c":["乘兴而来，冒雨过、徵君之宅。","相对者、诗家三老，酒徒八伯。","秉烛夜游行乐耳，一生能着千双屐。","看胜为可喜败欣然，如予弈。","痛饮也，肠千石。","剧谈也，唇三尺。","算樽前只少，红儿催拍。","便唱鹧鸪休听好，坐中半老江南客。","问阮公、醉后眼如何，全飞白。"]},{"t":"满江红 其十八 寿黄处安中书","f":"古风","c":["问客何来，自闽海、薄游吴苑。","忽举目、天涯烽火，故乡中断。","泽国江山惊战鼓，秋风零雨飞宾雁。","正登楼、作赋楚天高，愁王粲。","十月节，寒花绽。","千人石，清樽宴。","喜今朝初度，亲朋相见。","回首紫薇旧梦杳，放怀白发馀生健。","但摩挲，毛颖老中书，加餐饭。"]},{"t":"满江红 其十九 梦","f":"古风","c":["日日愁生，赖有此、枕中之夜。","我梦见、大千境界，无非假者。","花月春江堪舞蝶，烟波瀚海能骑马。","尽神游、万里姿逍遥，阆风野。","邯郸道，何潇洒。","阳台下，何妖冶。","但逢场作戏，机心都化。","乌有先生相对好，亡何乡里归休罢。","奈一声、鸡唱又天明，愁来也。"]},{"t":"凄凉犯 寒更","f":"古风","c":["愁人影共。","残灯语、夜寒何处寻梦。","淡月微笼，酸风乍咽，严更徐动。","孤衾自拥。","听声声、如迎似送。","想依稀、长歌短泣，数阕谯楼弄。","多少朱门客，锦瑟弹蛟，玉箫吹凤。","凄凉伴我，吉丁当、打入心孔。","断续随风，又接着、晓钟鸣空。","问鸡人、铜壶漏水几点冻。"]},{"t":"水调歌头 其一 赠隐者","f":"楚辞体","c":["左手招明月，右手引清流。","遂弃人间俗事、长伴赤松游。","春与猿兮吟啸，秋与鹤兮飞舞，八百岁春秋。","夜授南柯守，朝拜酒泉侯。","携玉杖，吹铁笛，酌金瓯。","醉乡高卧、掉头那问帝王州。","自谓羲皇以上，无论晋魏之事，涓子不能俦。","我亦问津者，愿泛武陵舟。"]},{"t":"水调歌头 其二 解嘲","f":"古风","c":["卿自用卿法，吾亦爱吾庐。","一生着几两屐、安用美哉车。","种得东篱五柳，饮得东皋五斗，此外又何须。","已梦我为蝶，谁识子非鱼。","书咄咄，称好好，解如如。","不如说鬼、妄言妄听莫辞无。","人贵及时行乐，我也逢场作戏，软饱黑甜馀。","莫问九州事，且卧一床书。"]},{"t":"水调歌头 其三 中秋","f":"古风","c":["秋月忽然好，游屐满山前。","远观灯火楼阁、万点小星悬。","逐队王孙公子，绕坐歌儿舞女，人压看场圆。","独有悲秋客，白眼对青天。","千古事，一场梦，总堪怜。","吴宫明月在否？","兴废几何年。","无限朱门绮户，也有竹篱茅舍，皓魄一般全。","休待玉箫彻，我欲卧渔船。"]},{"t":"水调歌头 其四 醉歌","f":"古风","c":["左手把杯酒，右手握刀镮。","快哉吾欲浮白、醉即舞双丸。","读罢一编遗史，断尽千秋公案，怒发每冲冠。","椎铁击秦政，挝鼓骂曹瞒。","而今事，增一笑，总般般。","人情大抵难测、翻覆似波澜。","休问英雄竖子，富贵合输公等，已矣复何言。","仰视四天白，长啸倚栏杆。"]},{"t":"水调歌头 其五 平远堂雨中送春","f":"古风","c":["山上云为雨，山下雨为烟。","不分烟与云处、只听雨潺湲。","旧雨送春归去，今雨倩人留住，去住总堪怜。","春入远天外，人立晚风前。","试煎茶，宜折柳，共题笺。","干戈未定、药酒今夕惜流年。","为问千人石上，妙舞娇歌何处，空谷一诗筵。","日暮下山去，骑马似乘船。"]},{"t":"水调歌头 其六 送陈次山","f":"古风","c":["三月莺花节，送子出青门。","我向离亭贳酒、弹汁染衫痕。","河畔萋萋芳草，陌上依依杨柳，极目总销魂。","往问广川子，几筴玉杯存。","橐须笔，携櫑具，贮罍樽。","但读离骚痛饮、醉即舞青萍。","试渡滹沱河北，还过邯郸城下，慷慨满乾坤。","去矣陈惊坐，舌在不须扪。"]},{"t":"满庭芳 其一 风雨夜怀卿谋","f":"古风","c":["折絮夭风，冻花侧雨，薄寒新上罗衣。","可怜人意，恰对可怜时。","几度思量往事，回首处、风景凄其。","难生受、黄昏院落，独自怎支持。","想伊人此际，笼香弄笔，剪烛吟诗。","待扁舟相访，梦到还迷。","只听数声征雁，断云里、叫过楼西。","呼来问、又推深夜，不肯寄书飞。"]},{"t":"满庭芳 其二 游娄东张氏园","f":"古风","c":["山出篱前，水周堂下，高轩插架朱藤。","亭台新绿，曲径隐斜曛。","正好清和天气，黄鹂唤、游女如云。","羁栖客、苦无柑酒，独坐吊残春。","当年行乐地，青帘白舫，夜醉红裙。","听钿筝瑶管，歌舞芳尘。","不见富平公子，楼中燕、空怨黄昏。","湖山畔、萧萧松柏，明月照孤坟。"]},{"t":"满庭芳 其三 偶语","f":"古风","c":["瓮里醯鸡，裈中蠛虱，人生大抵皆然。","蛮争触斗，割据几山川。","多少移山填海，凭意气、不肯由天。","下场头、总堪一笑，鼓罢戏文完。","算浮生如梦，转关得失，弹指悲歌。","且不如高卧，图取奇缘。","只恐梦中占梦，梦醒后、又费流连。","都输与、希夷老子，一觉便千年。"]},{"t":"满庭芳 其四 王烟客太常八十","f":"古风","c":["七叶门风，三槐世德，先生作述无忧。","笔精墨妙，名下更空俦。","富贵公家自有，但称寿、八十平头。","等而上、老彭八百，大树八千秋。","优游兴不浅，西田依杖，风月嘲讴。","看儿孙戏綵，白马青裘。","笑问香山洛社，齐年者、犬斗同浮。","吾家老、与君成二，来往亦风流。"]},{"t":"凤凰台上忆吹箫 梦亡友卿谋","f":"古风","c":["玉树生埋，香钩殉葬，人间无限伤心。","听山阳邻笛，泪破衣襟。","长忆连床对酒，灯影里、浅笑微吟。","斯人死，坐看卿辈，谁是知音。","追寻。","天边去也，盼十二楼中，雁断鱼沉。","甚风吹环佩，梦倚瑶琴。","依旧璧人一对，携手处、翠袖花簪。","应叹我，关山摇落，鬓发萧森。"]},{"t":"天香 咏龙涎香","f":"古风","c":["云气盘山，雨痕黏草，海天遥识龙睡。","细剪香涎，平分瑞脑，泛水渗沙同腻。","烟鬟雾髻，仿佛见、织绡娘子。","檀口唾花几点，丝丝篆成心字。","犹忆琐窗半闭。","袅金凫、共消残醉。","惆怅遗芳梦杳，蘅芜谁寄。","聚窟返魂何处。","空留下、馀薰旧鸳被。","赢取鲛人，玉盘珠泪。"]},{"t":"汉宫春 观演邯郸梦","f":"古风","c":["咄咄临川，能现梦中身，而为说法。","邯郸道上，一枕悲歌离合。","青驴黄犬，好妆成、红妻绿妾。","等闲看，鬼门关外，何殊洛阳宫阙。","休笑卢生痴绝。","算一场春梦，大家收煞。","黄梁半甑，炊过几朝年月。","曲终人醒，玳筵前、酒杯犹热。","又归来，独眠孤馆，今夜应添白发。"]},{"t":"烛影摇红 其一 寿吴冰仙夫人","f":"古风","c":["甲帐琼台，彩鸾初嫁年华妙。","红窗窈窕日无愁，但见嫣然笑。","笑尽珠围翠绕。","谁解受、笔封墨诰。","画帘乍捲，香篆微闻，湘纨淡扫。","金石摩挲，青编粉印看新稿。","酒阑灯灺忆当年，梦破巫山晓。","应是胡麻饭饱。","映桃花、风姿不老。","拼试轻鞭，几时搔背，麻姑乌爪。"]},{"t":"烛影摇红 其二 题女士张采于衡栖集和来韵","f":"古风","c":["地老天荒，悲歌不独江淹恨。","小庭风絮也关愁，林下重题韫。","应付莺花管领。","好看承、车香障锦。","胡然空谷，翠袖天寒，衡门栖隐。","绣户燃脂，彤奁占尽妆台韵。","断肠哀怨为谁吟，宛转萦方寸。","欲倩萧郎寄问。","早消除、风凄月闷。","试拈湘管，爱劈鸾笺，叠成方胜。"]},{"t":"声声慢 旅思用易安韵","f":"古风","c":["花开柳闭，燕去莺来，东君干甚休戚。","一样春风，二十四番消息。","朝来又添细雨，大江头、落潮偏急。","春莫去，纵他乡暂遇，故人曾识。","休笑春光已老，看镜里、白发数茎堪摘。","苦把春风留住，怎能吹黑。","空着枕头一半，听铜壶、泪点同滴。","这时节，便梦中、人到也得。"]},{"t":"梦扬州 客广陵用少游韵","f":"古风","c":["晚潮收。","叹隋宫、花月都休。","寒雨芜城，绿杨三月如秋。","市门十里黄埃满，但往来、车马星稠。","红桥畔，青楼底，谁人勾当春愁。","追想樊川狎游。","报书记平安，廿四桥头。","笑我多情，鬓丝禅榻空留。","纱灯万点归何处，枉断肠、锦瑟帘钩。","平白地，扬州梦醒，恼乱苏州。"]},{"t":"梦芙蓉 寒月","f":"古风","c":["一般明月夜。","最春园花里，秋山林下。","玉阶如水，枕簟也消夏。","三冬都告罢。","殿额广寒高挂。","顾影无人，只天边青女，相伴素娥寡。","我独徘徊旅舍。","梦想游仙，飘渺阆风野。","冰丸一颗，品色冷相射。","御风疑羽化。","何须歌舞台榭。","但买春醪，呼酒徒痛饮，编作客窗话。"]},{"t":"玉蝴蝶 其一 雪窗忆卿谋","f":"古风","c":["淅淅萧萧瑟瑟，疏疏密密，整整斜斜。","算有三分墙角，数点窗纱。","响茅檐、风敲断竹，迷野渡、月上平沙。","浪相誇。","瑶林琼树，种玉人家。","嗟嗟。","闭门高卧，羔儿无分，且吃团茶。","翘首天涯，空吟冰柱忆刘叉。","盼书邮、浮沉征雁，寻驿使、冷落梅花。","问君家。","剡溪不远，可泛星槎。"]},{"t":"玉蝴蝶 其二 贺高二亮纳姬湖州","f":"古风","c":["应是三生杜牧，深红浅绿，再接花枝。","正好珠珰佩解，金雀鬟垂。","定情诗、早怜碧玉，小名录、恰比红儿。","尽绸缪，描残翠管，写尽乌丝。","相宜。","绿衣方小，青衫未老，绛缕初飞。","顾曲郎君，记歌娘子按新词。","学秦筝、争传妾解，偷吴语、未许欢知。","画中人，五湖一叶，载到西施。"]},{"t":"念奴娇 其一 午日旅思","f":"古风","c":["葵花艾叶，依然是、前度端阳家数。","菰米兰桡问甚处，吊望楚天云树。","乳燕初飞，流莺三弄，几阵黄梅雨。","飘零湖海，何堪萧寺孤注。","遥念寂寞纱窗，菖蒲剪了，黯停杯无语。","别恨离愁添几许，鬼病恹恹情绪。","整日沉眠，梦魂无赖，不到长洲路。","除非借取，画船竞渡归去。"]},{"t":"念奴娇 其二 赠吴梅村先辈用东坡赤壁韵","f":"古风","c":["江山如梦，叹眼前、谁是旧京人物。","走马兰台行乐处，尚记纱笼题壁。","椽烛衣香，少年情事，头白今成雪。","杜陵野老，风流独数诗杰。","更听法曲凄凉，四弦弹断，清泪如铅发。","莫问开元天宝事，一半晓星明灭。","我亦飘零，十年湖海，看雨丝风发。","何时把酒，浩歌同送明月。"]},{"t":"念奴娇 其三 和羡门韵","f":"古风","c":["百年弹指，奈头颅渐秃、肝肠如碎。","飞将高皇时不遇，却遇灞陵亭尉。","感慨何为，不如归去，也学糊涂醉。","文章九命，此生万事难遂。","眼看世态悠悠，西江有水，不到枯鱼肆。","脱了青衫披绿箬，且饱银丝鲜脍。","弃蚁亡羊，于鱼得计，吾读徐无鬼。","人间不乐，相忘惟一回睡。"]},{"t":"念奴娇 其四 和羡门韵","f":"古风","c":["先生休矣，叹元龙豪气、俯同群碎。","借问史公牛马走，岂苦烂羊都尉。","满座貂蝉，狗偷鼠窃，偶尔乘天醉。","何如寻取，当年初服堪遂。","君见入市者乎，朝来骈足，日暮成空肆。","损益盈虚都似此，所以步兵思脍。","紫绶耶叉，绯衣罗刹，群小皆名鬼。","署门谢客，主人今日鼾睡。"]},{"t":"念奴娇 其五 送孙无言归黄山和顾庵韵","f":"古风","c":["忽闻长啸，是苏门鸾鹤、遗音清绝。","弹铗归来櫑具剑，更铸山田耕铁。","手拍浮丘，吾庐偕隐，漫卷君卿舌。","署门谢客，白云无处停辙。","回首花月扬州，几年梦醒，暂赋芜城别。","骑鹤吹箫人在否？","笑看迷楼烟热。","垂老生涯，首阳柳下，计较谁工拙。","迟君赠我，三十二峰寒雪。"]},{"t":"念奴娇 其六 飞涛其年云客既庭御之枉叙草堂和飞涛韵","f":"古风","c":["古人安在，总上场优孟、下场翁仲。","天壤之间存我辈，聊尔一觞一咏。","伧父左思，老兵阮籍，歌辨衙官宋。","当杯行令，戏猜三两横纵。","酒后耳热狂呼，濡毫呵壁，欲把天公控。","趁取吴宫春未老，甘与梨花同梦。","银烛方长，铜壶初滴，路近东西弄。","诸君且住，床头尚满青瓮。"]},{"t":"念奴娇 其七 饮梁宗伯蕉林书屋赋赠","f":"古风","c":["疏帘清簟，正高卧、南面百城书屋。","丘壑夔龙权寄傲，勾当午桥松菊。","白袷论兵，深衣习礼，总付渔樵曲。","东山未起，中年聊写丝竹。","今夜河朔开樽，止谈风月，醉扫愁千斛。","咫尺长安君不见，顷刻浮云翻覆。","紫禁宣麻，黄扉视草，早叶金瓯卜。","江南野老，梦留东阁桦烛。"]},{"t":"念奴娇 其八 归兴","f":"古风","c":["回车哭罢，忽仰天大笑、冠缨索绝。","大抵长安局似弈，正打辘轳双劫。","东阁除书，西台弹事，早暮分凉热。","一言以蔽，无财不可为悦。","君看游客纷纷，吹芋鼓瑟，槐柳森齐列。","何异乞儿争向火，转眼灰飞烟灭。","或问先生，何为至此，仆亦无言答。","掉头归去，闭门独卧寒雪。"]},{"t":"念奴娇 其九 题席次文出猎图和梅村韵","f":"古风","c":["是何年少，向长城饮马、沙场结客。","台上呼鹰垆下醉，尚弄数行题墨。","投笔归来，东山射虎，大羽犹能没。","画图留取，黄云万里秋色。","我亦蛮府参军，短衣长剑，喜逐将军猎。","回首卢龙成旧梦，变作阳关三叠。","仰屋看书，叩门乞食，恨少朱家侠。","相逢痛饮，头颅如许堪惜。"]},{"t":"念奴娇 其十 咏米家灯和其年韵","f":"古风","c":["尚书堂上，忽鸾飞凤舞、花枝分亚。","起剔银灯相视笑，认得米家书画。","木偶儿郎，弓腰仕女，游戏无真假。","针神妙手，恰从阿堵传写。","正是月满千街，星移万点，天放元宵夜。","遥想汉宫传蜡烛，光照彩楼缥瓦。","玉漏停催，琼箫慢弄，暂醉珠帘下。","燕台胜景，剪灯重谱新话。"]},{"t":"念奴娇 其十一 羡门五十一岁夫人四十九岁十月得子名曰百龄是可贺也调百字令","f":"古风","c":["世间奇事，看木公金母、合成百岁。","夫妇平分大衍数，阳进因而阴退。","进若有余，退非不足，损益刚相配。","乃生男子，美哉则百之端。","以是名曰百龄。","在百家姓上，百官图内。","好似百花兰桂发，百鸟鸾凤出类。","书读百篇，财盈百宝，百禄天生备。","贺君百喜，百壶索取同醉。"]},{"t":"桂枝香 其一 月下","f":"古风","c":["晚风摇曳。","渐吹落残乌，素娥睡起。","惊看镜殿堆玉，晶宫映水。","井梧飒飒敲窗纸，怨鸿啼、芦花岸里。","黄昏院落，画栏独倚，寸心如死。","秋色三分将尽矣。","更寒烟满目，疏钟第几。","四壁虫声助予，叹息而已。","南飞乌鹊无枝止，笑归来、昨非今是。","今夕何夕，举杯邀月，陶然醉耳。"]},{"t":"桂枝香 其二 咏蟹","f":"古风","c":["漫寻尔雅。","见介士横行，郭索盈野。","最爱绀甲青匡，金膏雪炙。","吴江公子肠应断，甚西风、酒旗潇洒。","相逢何处，沙汀渔火，村庄茅舍。","记卓女、长卿初嫁。","为彭越低眉，停箸不下。","我亦蝤蛑，暗想妆台愁把。","香橙手劈吴盐细，欲持螯、谁传杯斝。","霜华满地，黄花已老，玉人去也。"]},{"t":"齐天乐 咏蝉","f":"古风","c":["小园疏柳斜阳晚，凄然数声低唤。","吸露频啼，迎风乍咽，迸出悲丝急管。","宫商偷换。","和五夜寒螀，一天哀雁。","恨杀螳螂，惊回焦尾鹍弦断。","当年齐女曾变。","故宫衰草外，何限秋怨。","罗袂无声，玉墀尘满，落叶几番零乱。","余音宛转。","想动影低鬟，妆残帘捲，杜甫山妻，夜飞人不见。"]},{"t":"水龙吟 其一 杨花和东坡韵","f":"古风","c":["美人满院红妆，绿珠忽向高楼坠。","非云非雨，非朝非暮，一天春思。","绣阁娇慵，厌他轻薄，重门深闭。","奈偷从墙角，窣来窗畔，人前故眠羞起。","可惜风流扫地，赖多情、青苔牵缀。","生成薄命，飞来又被，鹦哥啄碎。","一缕残魂，浮萍再世，去随流水。","想深宫拾得，踏歌连臂，有人垂泪。"]},{"t":"水龙吟 其二 杨花和东坡韵","f":"古风","c":["卷帘但见飞花，何时开起何时坠。","玉人如梦，随风游戏，几多愁思。","为问章台，青青在否？","宫眉应闭。","剩蛮腰解舞，飘飖上下，还学三眠三起。","分付雕梁燕子，好衔将、小巢萦缀。","谢娘纤手，搓来捏去，团成复碎。","忽地伤心，人间天上，落花流水。","倩软绵堪拭，此中洗面，只馀清泪。"]},{"t":"水龙吟 其三 咏白莲","f":"古风","c":["谁家渌水银塘，凌波扶出霓裳女。","天然素面，冰肌玉骨，暗香销暑。","采向吴宫，画船相傍，盈盈解语。","看碧天凉夜，风清月晓，长依白鸥为侣。","几处红衣乱舞，翻嫌他、脂匀粉涴。","蓬茅綦缟，铅华洗尽，淡妆偏妩。","最恨西风，断魂憔悴，几番秋雨。","叹随波败叶，飘零只滴，泪珠如许。"]},{"t":"瑞鹤仙 慈仁寺松","f":"古风","c":["岁寒寻老友。","只萧寺乔松，交情耐久。","吾衰甚矣惫。","故人喜相见，支离群叟。","春风桃柳。","满长安、红争绿斗。","让髯公、沐雨梳霜，到底青青依旧。","安否。","九逵哄处，五市开时，货财辐凑。","衣冠奔走。","洒斯辱，浇杯酒。","劝怒涛休吼，晨钟暮鼓，且共佛灯厮守。","更呼来、鹤唳长空，一天星斗。"]},{"t":"石州慢 和高季迪韵","f":"古风","c":["花信频催，二十四番，雨飘风洒。","多情最是风流，杨柳瘦腰一把。","树犹如此，何况人倚阑干，游丝和梦愁牵惹。","泪断锦回文，借乌丝重写。","姚冶。","玉人应在，燕子楼中，湘帘垂下。","记得青鬟，微笑红牙轻打。","而今寂寞，空想院落秋千，几时再驻墙头马。","蓦听杜鹃啼，道东君归也。"]},{"t":"拜星月慢 惜别","f":"古风","c":["香雾云鬟，清辉玉臂，双照泪痕犹在。","忍令分携，怯空房难耐。","无人处，生怕落花风起，轻把檀痕吹坏。","惜惜情怀，料身中不快。","问何曾、走马章台内。","又非因带甲榆关外。","何苦东去西飞，判相思分界。","看弹琴、谁写芙蓉黛。","伴薰香、莫绾鸳鸯带。","只好教、笼里鹦哥，咒那人无赖。"]},{"t":"花犯 西山晴雪","f":"古风","c":["遍皇州玉龙纷舞，千门六花绕。","燕台高眺，见一点西山，装作琼岛。","翠微低处斜阳照。","朔风飘不了。","掩映着、瑶林琪树，烟中飞白鸟。","我来蓟丘，笑行囊空馀几两屐，卧游难到。","灞桥畔，趁不上、剡溪一棹。","翻追忆、故园雪夜，万峰里、梅花消息早。","只好倩、小楼铁笛，吹霜天角晓。"]},{"t":"喜迁莺 立冬","f":"古风","c":["朝看月令。","是律中应钟，神司元冥。","寒日模糊，阴风凛冽，一扫秋光无剩。","谁遣倪迂妙手，写出灰堆冬景。","茅檐下，听数声铁马，冬冬相应。","长安多肉阵，凤碳檀炉，低唱羊羔饮。","闭户先生，拥书枯坐，只好敲冰煮茗。","莫怪天公作恶，雅称玉堂官冷。","青镜里，惊漫空霜雪，又添双鬓。"]},{"t":"绮罗香 咏香","f":"古风","c":["髻鬌初梳，诨褠乍脱，文几鹊炉先置。","银叶如钱，半晌篆烟才度。","绕纱橱、为雨为云，罩绣阁、非花非雾。","更怜他、入袖穿裳，徐徐引到销魂处。","玉人体自生香，借三分迷迭，助成佳趣。","心字装成，还向月中微步。","谶好事、喜结双丝，诉幽情、私添一炷。","付钿盒、小玉珍藏，莫放郎偷去。"]},{"t":"二郎神慢 李笠翁招饮观家姬新剧","f":"古风","c":["百花巷。","乍小队、花神来降。","看面似芙蓉眉似柳，点素额、檐梅初放。","莲袜榴裙花下舞，桃叶渡、采菱新唱。","湘帘捲、兰香暗度，风动罗衣微飏。","惆怅。","分明仙乐，大罗天上。","听赵瑟秦筝吴苑曲，妒杀粉君脂相。","自笑周郎愁眇眇，好央及、灯花剔亮。","怕飞逐彩云，牢系鸾凤，重重绡帐。"]},{"t":"归朝欢 澄海楼","f":"古风","c":["家在芙蓉江畔住。","两桨沙棠桃叶渡。","天风吹我北溟来，芒羊一望无穷处。","漫将秋水注。","此时好读玄虚赋。","倚危楼，不闻呼啸，满耳惊雷雨。","却怪冯夷缘底怒。","白马乘潮鸣急鼓。","鲛人又喜起楼台，璇宫出市珊瑚树。","风鬟雾髻女。","戏弹宝瑟来迎汝。","趁渔舟，一声欸乃，送我蓬壶去。"]},{"t":"望海潮 观猎","f":"古风","c":["辽西重地，东临碣石，朔风塞马萧萧。","台上呼鹰，碛中走狗，千人弓箭横腰。","牙纛抗招摇。","看雕翎落处，雨血风毛。","日暮山空，寒乌饥兔正悲号。","将军坐地分曹。","有健儿行炙，美女弹槽。","再打一围，扬鞭归去，戍楼画角声高。","何似霍嫖姚。","笑当年猿臂，射石空劳。","顾语参军，醉中磨盾好挥毫。"]},{"t":"望湘人 闺信","f":"古风","c":["自君之出矣，独宿空房。","绣衾慵爇龙脑。","背着灯儿，侧身帐底，多半和衣睡倒。","帘幕花香，栏杆燕语，月明如晓。","好良宵、满院春风，不见断肠人到。","乍梦被郎呼去，向画屏深处，轻怜低笑。","正勾当相思，一晌销魂未了。","无端撼起，流苏微动，蓦地把人惊觉。","闲滋味、费尽思量，私下报郎知道。"]},{"t":"风流子 醉中作","f":"古风","c":["吾生祈一梦，将进酒、结客少年场。","愿贵比五官，芙蓉车盖，艳齐三妇，玳瑁钗梁，封侯事，建牙刑白马，挽箭射黄獐。","鼓吹归来，角巾辞去，拍肩泰华，濯足沧浪。","醒来都不是，看衣鹑马狗，两鬓秋霜。","赢得一官孤竹，三径柴桑。","只宋玉招魂，偶逢神女，相如草赋，曾视君王。","且向樽前醉也，长短歌行。"]},{"t":"疏影 黄梅花","f":"古风","c":["花神戏法，向园林剪彩，点缀残腊。","磐口玲珑，荷盖团圞，仿佛香生金鸭。","前身本是江妃种，催妆早、先来一霎。","恰阿娇、初染鹅黄，纤指栏边偷捻。","耐尽霜偎雪压，爱自然幽雅，不近蜂蝶。","我梦罗浮，错认佳人，赚得翠禽嘈杂。","当年倚袖天寒日，插蝉鬓、夜藏犀合。","到而今、携向纱窗，空有泪花凝蜡。"]},{"t":"霜叶飞 黄芽菜","f":"古风","c":["吾家老圃东篱下，曾将野菜修谱。","但知春韭与秋菘，食荠肠还苦。","今领略、长安杂俎。","黄芽一把和盐煮。","觉入口甘香，似燕赵、佳人风致，冷淡如许。","君看辇上华筵，金齑玉脍，谁向此君下箸。","偏生我辈一条冰，堪作冰壶侣。","任嚼出、宫商徵羽。","只愁面色平分取。","却回思、故乡味，千里莼羹，惟吾与汝。"]},{"t":"宣清 玉河冰","f":"古风","c":["黑帝乘权，爰命波臣，晶宫大开冰屋。","砌黄河、粉壁万层，掩青江、银练千幅。","晓入金门，环桥一望，果然如玉。","正平铺，凤楼前，寒光直射朝旭。","天子诏凌人，宜藏北陆，百官赐饮足。","纵镂树成花，凝檐作筋，天画文章，未必重瞳娱目。","念乡村、荒田野哭。","问边庭、铁衣起粟。","何时泮澌借太液恩波，布春风、暖生寒谷。"]},{"t":"沁园春 其一 送穷","f":"古风","c":["咄咄穷来，冰氏主人，劝汝千杯。","怪子云高阁，一麾不去；","昌黎上座，三揖仍回。","饿倒翳桑，冻穿东郭，拊手揶揄笑我该。","何相厄，出门如有碍，闭户如呆。","特凭毛颖符牌。","择吉日车马走天涯。","向簟瓢巷里，生前可住；","首阳山下，死后堪埋。","耕砚为田，积书作库，今后休将壁立猜。","穷唯唯，吾从此逝矣，赠子多财。"]},{"t":"沁园春 其二 释愁","f":"楚辞体","c":["试望愁城，天地无光，壮士吞声。","奈悲秋宋玉，不堪长恨；","伤春杜牧，未免多情。","万斛纷来，百端交集，方寸之心难与争。","叹人世，黯然销魂，惟此为深。","仆今奉教先生。","毋劳尔神兮摇尔精。","使王乔与我，遨游而逝；","黄公与我，歌咏而行。","寂寞为床，玄虚为宇，叱咤驱愁服上刑。","愁休矣，逝将适乐土，实获吾心。"]},{"t":"沁园春 其三 遣病","f":"楚辞体","c":["若有人兮，蒲柳风姿，憔悴支离。","恨雍容司马，抛残赋草；","风流沉约，瘦损腰肢。","扁鹊低头，巫咸束手，丈室维摩亦皱眉。","数其罪，合先诛二竖，后斩三户。","飘然与彼长辞。","况苦口良方我有之。","倩冀州坐客，挥毫草檄；","少陵野老，信口吟诗。","左援桐君，右携欢伯，楚客高谈七发词。","涣乎一，涊然其汗出，是乃良医。"]},{"t":"沁园春 其四 反止酒","f":"古风","c":["陆醑前来，枚卜功臣，众口交推。","彼从事齐州，清为圣德，督邮鬲县，浊亦贤才。","尧舜千钟，仲尼百斛，子路宁辞十榼陪。","髡一石，更先生五斗，学士三杯。","尝闻上顿长斋。","即乘马骑驴事尽佳。","况卓家少妇，为君涤器，杨家妃子，为我持罍。","山带兰陵，水连桑落，曲部分茅议允谐。","咨汝醑，俾侯醴泉郡，曰往钦哉。"]},{"t":"沁园春 其五 罪酒","f":"古风","c":["醑若毋声，以酒为名，乃罪之魁。","算持蟹螯者，瓮中就缚，吹龙笛者，水底长埋。","金盏才擎，玉山便倒，玩我真如儿戏哉。","腐肠药，甚良醪可恋，心腹当灾。","今朝焚了糟台。","又何问莲花白玉杯。","倘君将伐狄，臣当执御，人能击杜，我愿持槌。","草夺黄封，驱除绿蚁，主爵壶商赐自裁。","醑不道，削汝懿侯职，以惊将来。"]},{"t":"沁园春 其六 梦卿谋","f":"楚辞体","c":["有美人兮，携手同行，其乐只且。","喜化为蝴蝶，中宵起舞，唤他啼鸟，野店提壶。","一唱高山，再歌流水，听者钟期鼓者俞。","长太息，曲高而和寡，其信然欤。","顾君与我何如。","彼天下纷纷安足拘。","叹故人千里，远遗端绮，主人仓卒，遽赠文无。","蕙带荷衣，倏来忽逝，乌有先生对子虚。","开户视，不见其处矣，搔首踟蹰。"]},{"t":"沁园春 其七 题李镜月庐游日记次西樵韵","f":"古风","c":["奇绝青莲，几辆芒鞋，直踏匡江。","向香炉峰下，呼来慧远，珠帘谷口，吸出康王。","五老婆娑，九云飘渺，三叠流泉喷石冈。","还识否？","是庐山面目，仔细端相。","小奚亟解诗囊。","看摇笔高吟字万行。","笑近骑白鹿，踢翻星渚，远携黄鹤，飞过浔阳。","君已逍遥，仆犹惆怅，画壁鸣琴寄兴长。","问何日，把惊人谢眺，搔首青苍。"]},{"t":"沁园春 其八 和阮亭偶兴","f":"古风","c":["无可奈何，旧事南柯，新恨东流。","叹易变人情，幻如演戏，难猜世法，闷似藏钩。","闭户无容，出门有碍，何况崎岖历九州。","不堪者，看宫中狗监，关内羊侯。","头颅如许谁酬。","但醉里乾坤姿拍浮。","算冥冥高飞，于人无怨，悠悠行迈，谓我何求。","蝴蝶前身，杜鹃今日，伯仲之间海上鸥。","乃所愿，学丈人荷蓧，男子披裘。"]},{"t":"沁园春 其九 和阮亭偶兴","f":"楚辞体","c":["我所思兮，濯足清流，晞发高冈。","奈举国侏儒，臣饥欲死，满堂酒汉，公醒而狂。","学剑不成，卖浆未售，肘后难传疗恨方。","除非是，学中山千日，梦到羲皇。","觉来起舞淋浪。","且读破离骚续九章。","喜庄子逍遥，人呼以马，左慈狡狯，或化为羊。","手弄双丸，目空九点，竿木随身作戏场。","今而后，从子虚隐矣，何有之乡。"]},{"t":"沁园春 其十 戒游","f":"古风","c":["子好游乎，游必有方，吾语子游。","惟辇上贵人，峨冠博带，堂中公子，肥马轻裘。","十日交驩，千金解赠，主既逢迎客亦留。","非然者，恐闭门不纳，怀刺谁投。","况君白发盈头。","便鼓瑟吹箫枉自羞。","奈弹铗而歌，食终不饱，执鞭以御，富也难求。","莼鲙秋风，一官久弃，肯向侯门走马牛。","君休矣，听数声欸乃，雪夜归舟。"]},{"t":"沁园春 其十一 戒游","f":"楚辞体","c":["我学渊明，归去来兮，请绝交游。","有草阁三间，久盟息壤，秫田十亩，将老菟裘。","山水乡邻，梅花妻妾，小部声音黄栗留。","出门去，怕青天剑啸，沧海珠投。","而今金尽床头。","纵舌在何辞仰面羞。","叹富贵才高，骄人易取，文章命薄，知己难求。","乘兴而来，途穷则返，笑傲随他呼马牛。","从今后，把世情看破，飘瓦卢舟。"]},{"t":"沁园春 其十二 题蛟门三好图","f":"古风","c":["咄咄汪生，少年行乐，三好兼全。","只饮酒离骚，便称名士，吹箫弄玉，定作神仙。","椽烛隃麋，远山丽竖，小宋风流剧可怜。","谁消受，疑梦游蓬岛，醉享钧天。","画图到处流传。","得饱看红妆也有缘。","但酒癖书淫，恐妨万事，歌残舞散，难驻千年。","仆病停沽，吾衰畏解，文籍先生高枕眠。","君休矣，是有虽可喜，无亦欣然。"]},{"t":"沁园春 其十三 题五苗图","f":"古风","c":["望气佳哉，蕉林书屋，得宝隋和。","看皋庑家声，天边台斗，彩鸾国色，地上姮娥。","玉燕投怀，石麟露角，更胜珠哥与户哥。","徵兰梦，记五苗丝绣，玉叶金柯。","不惟孔释摩挲。","有后稷携来瓜瓞歌。","算学士文章，原名陶谷，将军勋业，也号田禾。","左握干戈，右持俎豆，何似堂封万石多。","询占者，是翁官农父，儿取高科。"]},{"t":"沁园春 其十四 司农招饮携五苗出揖客复次前调奉赠","f":"古风","c":["今日华筵，珠帘深处，唤出苗哥。","看头角硗硗，宛然玉粒，双眸炯炯，秀似琼禾。","花帽荷衣，深躬浅喏，年少偏生礼数多。","问其岁，是卯君诞降，月窟婆娑。","岂惟字识之无。","便好应朝廷童子科。","算唐室校书，八龄刘晏，秦家相国，十二甘罗。","第五之名，何如第九，笑问先生喜若何。","先生笑，谓诸君醉矣，为我高歌。"]},{"t":"沁园春 其十五 题孙赤厓携孙小像","f":"古风","c":["万里归来，管宁无恙，吾谷闲行。","但觅取虎头，传神阿堵，携将麟角，绕膝如馨。","君善秦声，妇能鼓瑟，画里家山聊遣情。","相尔汝，惟日沽一斗，笑看三星。","十年辽海飘零。","曾短布驱车铁岭城。","记汉殿凌云，马卿献赋，梁园雨雪，枚叟谈经。","阊阖天高，巫阳梦远，仆亦悲歌泪满缨。","空凝望叹王孙桂树，芳草青青。"]},{"t":"沁园春 其十六 赠董舜民","f":"古风","c":["谁踞词坛，天下健者，独有董公。","曾北上燕台，东游越峤，南寻隋苑，西问秦宫。","慷慨悲歌，滑稽笑骂，左把刀钩右酒钟。","挥毫罢，令雪儿起舞，唱彻回风。","君才十倍吴蒙。","更林下夫人兴致同。","看绿绮低弹，风吹鬓影，青蛾淡扫，月上眉峰。","放棹探梅，拥炉煨芋，乐事相于闺阁中。","还索取，将红桥锦字，好配林鸿。"]},{"t":"沁园春 其十七 李渭清赠龙须一茎赋此酬之","f":"古风","c":["为问何年，龙战山东，堕此长须。","曾阶于尺木，能兴云雨，贮之勺水，便化江湖。","今也卷然，手携在箧，犹见虬髯气色殊。","还恨未，向九仙馆里，捋取羊珠。","顾君赠我何如。","好准备尊前牙杖需。","算虾须虽细，可编帘箔，鱼须甚壮，亦树旌旟。","差胜衰翁，白髭似戟，不中卢仝唤作奴。","却自笑，看吟成五字，剩数茎无。"]},{"t":"摸鱼儿 其一 春怨","f":"古风","c":["问东君、赚春何意，春来还见春去。","满园花事刚三五，都付断肠风雨。","花尚尔。","又况是红颜、薄命愁眉妩。","美人日暮。","便红豆歌成，翠盘舞罢，难买君王顾。","看千古，总是风流易误。","秭归空筑青墓。","梅妃休怨楼东赋，吊取马嵬黄土。","君莫诉。","君不见英雄、失路还悲古。","楚歌楚舞。","试去听琵琶，青衫红袖，双泪几行数。"]},{"t":"摸鱼儿 其二 咏莼","f":"古风","c":["问江姝、宝钗半股，又绕青丝一缕。","洞庭渔父扁舟远，摘尽吴头楚尾。","谁得似。","似放诞文君、柔滑如脂体。","佳人水沚。","算不比浮萍，波漂露宿，何事名千里。","东曹掾，为尔挂冠归去。","西风昨夜还起。","愁予老系京华梦，正恐欲归无计。","归也未。","便一棹家乡、偕隐无人矣。","春前尚记。","想素手调羹，和盐伴豉，饱识厨娘味。"]},{"t":"摸鱼儿 其三 咏窝丝糖和其年韵","f":"古风","c":["问谁家、吹箫深处，锦丝袅就连理。","十分崖蜜三分脆，更胜枣儿堪嗜。","长安市。","喜今夕同探、官茧灯檠底。","君须尝此。","是元日膏饧，都城风俗，卖取胶牙齿。","还停箸，忽忆西京杂记。","娙娥别样新制。","白头宫监传遗样，曾识开元妃子。","形虽似。","空夜雨昭阳、不见红尘荔。","关卿何事。","但肠断东风，灞桥杨柳，愁看游丝细。"]},{"t":"贺新郎 其一 塞上","f":"古风","c":["天末卢龙道。","看敷分、山崖耸峙，河流低绕。","极望长城烟一抹，但见黄榆白草。","又添得、孤鸿飘渺。","寒月如霜沙似雪，想当年、有客伤心早。","重画出，边愁稿。","短衣自倚高楼啸。","吊西风、一杯残酒，泪痕多少。","漫说明妃出塞苦，不见玉关人老。","更减尽、英雄怀抱。","剩有琵琶浑不似，倩庐儿、弹出凉州调。","公莫舞，乌啼了。"]},{"t":"贺新郎 其二 贺荔裳纳姬举子","f":"古风","c":["宋玉高唐赋。","更相逢、洛川绣枕，袁家新妇。","碧杜红兰香不已，间以明珠翠羽。","正解佩、吴宫春暮。","蝶粉蜂黄都褪了，看雕梁、燕燕交交乳。","衣带缓，低眉妩。","梦中神女亲携付。","宁馨儿、天上石麟，人间绣虎。","才听啼声知大物，豪气略如其父。","请脱帽、为公狂舞。","玉果金钱汤饼会，愧无功、厚赉吾能与。","只愁写，弄璋句。"]},{"t":"贺新郎 其三 旅思","f":"古风","c":["岁月能如许。","问愁人、更经消得，几番羁旅。","白发悲秋灯下咏，生受纸窗风雨。","更添得、数声砧杵。","敲破客心千寸碎，枉教人、梦断江南浦。","雁叫也，又平楚。","浇愁惟酒差堪语。","忽伤心、此身饮罢，茫无归处。","空自珠帘◇画烛，看尽清歌妙舞。","但赢取、青衫泪苦。","红袖殷勤休劝醉，奈鬓丝、禅榻闲眉妩。","老去也，诉渔鼓。"]},{"t":"贺新郎 其四 端午和刘潜甫韵","f":"古风","c":["小满吴蚕吐。","乍阴晴、春红消歇，黄梅迎暑。","刮眼风尘纷未了，遍地蒲人艾虎。","何处觅、龙舟竞渡。","横笛短箫江上远，但关山、烽火传鼙鼓。","请拔剑，为君舞。","花花世界遽如许。","算英雄、百年成败，一杯残醑。","金紫貂蝉长在否，不抵枕中炊黍。","又看尽、蛮争触怒。","读破离骚还痛饮，叹吴侬、更比湘累苦。","只一醉，忘今古。"]},{"t":"贺新郎 其五 九日感旧","f":"古风","c":["偶过慈仁寺。","看门前、五株松树，婆娑尽矣。","二十年来风景异，不谓树犹如此。","感旧事、攀条流涕。","白发青衫驱款段，笑无端、贳酒荆高市。","听击筑，悲风起。","又逢佳节黄花里。","怅登高、西山残照，暮云千里。","极望齐州烟九点，家在吴头楚尾。","添几幅、荒丘废垒。","汉寝唐宫何处问，只滔滔、不断浑河水。","买一棹，吾归耳。"]},{"t":"贺新郎 其六 立秋夜雨","f":"古风","c":["又是秋来矣。","乍回头、悠悠长日，去如流水。","不觉西风吹老至，华发星星添几。","思往事、潸然出涕。","我自多愁泪洗面，问天公、何苦愁如此。","下一夜，霖铃雨。","声声滴碎惊秋耳。","助凄凉、三年客舍，故乡千里。","白首冯郎休说恨，尚对孺人稚子。","恨莫恨、别离生死。","不信愁人愁不寐，但愁魂、缭绕残灯里。","听漏点，三更起。"]},{"t":"贺新郎 其七 七夕和韵","f":"古风","c":["七七佳期矣。","看迢迢、明河清浅，盈盈一水。","别去一年来一度，毕竟欢娱能几。","想牛女、相逢流涕。","天上人间都不异，但有情、未免谁遣此。","洒泪也，今宵雨。","如侬只是鳏夫耳。","望家乡、邈如天汉，暮云千里。","三载断肠闺梦杳，添得玉楼思子。","哭长史、终当情死。","苦忆少年瓜果会，向凉阶、私语星光里。","唤不醒，姮娥起。"]},{"t":"贺新郎 其八 中元再和","f":"楚辞体","c":["问夜如何矣。","早鸡鸣、长安门外，车如流水。","争羡朝班仙仗好，老我闷怀有几。","端不为、洛阳流涕。","闻道地官初放赦，想魂兮、游戏应来此。","又遇着，廉纤雨。","归来惟有高眠耳。","君莫问、吹笙击磬，南邻北里。","欲向兰盆礼古佛，借我消忧幢子。","更解脱、无常生死。","同病最怜阳羡客，和哀弦、弹泪乌丝里。","歌一曲，秋风起。"]},{"t":"贺新郎 其九 中秋再和","f":"古风","c":["作客三年矣。","到中秋、天门街上，月明如水。","为问古时月尚在，照过今人有几。","几欢笑、几人泣涕。","明月原无圆缺恨，只人间、离合悲如此。","一霎变，风和雨。","我今为月徘徊耳。","念家山、乱云遮断，美人千里。","待挹酒浆倾北斗，吞尽兔儿桂子。","更莫管、明生魄死。","但得嫦娥相顾盼，放白头、醉舞霓裳里。","听水调，歌头起。"]},{"t":"贺新郎 其十 九日再和","f":"古风","c":["四见重阳矣。","怅悲秋、他乡何处？","登山临水。","为问诸公高宴会，遍插茱萸有几。","何必学、牛山掩涕。","我忆楞伽湖畔路，是少年、行乐尝过此。","吟一句，满城雨。","追寻昨梦依然耳。","惊回头、歌台舞榭，半成蒿里。","戏马龙山今在否，争甚英雄竖子。","谁保得、古而无死。","但趁清秋风日美，酹黄花、侧帽斜阳里。","怕转盼，寒沙起。"]},{"t":"十二时慢 观猎","f":"古风","c":["望平原、连天野烧，猎猎风吹千骑。","缚裤褶、雕弓韝臂。","盘尽山头谷尾。","犬走鹰飞，猿啼雁叫，洒血成红雨。","到日暮、叠鼓鸣笳，酹酒烹鲜，再杀一回足矣。","记少日、卢龙塞上，蛮府参军无事。","戏逐孤儿，短衣匹马，射虎南山里。","载黄獐满车，归从妻子誇示。","叹残年、抚髀生肉，郁郁谁能堪此。","索米金门，摊书玉局，见猎空欢喜。","问先生谁伴，嗟乎子虚亡是。"]},{"t":"兰陵王 伤春","f":"古风","c":["江南陌，袅袅东风弄色。","垂杨畔、宝马香车，芳草王孙自相索。","美人云鬓侧。","梦破残红半碧。","寻春去、莺送燕迎，十二栏干夜犹立。","繁华等陈迹。","但雨涩莓苔，风动葵麦。","游丝漠漠和愁织。","试目极千里，断烟寒食，邻鸡野哭如昨日。","落花泪盈尺。","追忆。","恨何及。","问老去东君，争似书客。","天荒地远无人识。","算往事只付，数声渔笛。","今宵沉醉舞短剑，歌昔昔。"]},{"t":"多丽 夏景","f":"古风","c":["画梁间。","日长午梦初残。","倚薰风、晕红如醉，无言情思阑珊。","捲桃笙、自寻坠珥，掩金诃、斜扑轻纨。","茉莉茶甘，鹧鸪香细，尽堪消暑小屏山。","无心理、钿筝瑶管，棋局也慵弹。","闲排遣、白敲冰脆，红点梅酸。","侍儿报、花梢月上，清光怯射越罗单。","浴兰汤、微揩粉汗，插犀梳、乱挽云鬓。","院落沉沉，夜凉似水，萧郎频唤展琅玕。","还一笑、背人行去。","等待向更阑。","却寻到、蔷薇架下，独凭栏杆。"]},{"t":"六州歌头 有客劝予出山者书此答之","f":"古风","c":["客何为者，劝我曳长裾。","人所爱，热官耳，顾愁予。","不相如。","君见居官者，苦思虑，劳筋骨，工笑语，勤奔走，乃多誉。","我则异于是矣，体多病、药物长须。","惯科头晏起，懒向府中趋。","礼法全疏，古之愚。","兼长扪虱，喜曝背，时强项，或撚须。","诸若此，皆不可，一朝居。","爱吾庐。","种豆南山下，几个竹，映芙蕖。","驱山犊，弹野雀，钓江鱼。","况有老妻酿酒，任醉后、拊缶歌呼。","有山公启事，报以绝交书。","客且归欤。"]},{"t":"临江仙 午日","f":"古风","c":["庭砌香蒲一剪绿，纱窗梅雨萧萧。","闹妆儿女彩丝飘。","珠帘桃叶渡，画鼓木兰桡。","唤起湘累休竞渡，云旗游戏波涛。","江潭独醒转无聊。","古人应让我，饮酒读离骚。"]},{"t":"一剪梅 和李易安韵","f":"古风","c":["织锦机边蟋蟀秋。","万里江风，吹送郎舟。","空闺无处说相思，独夜鸣琴，西北高楼。","弹罢清商两泪流。","妾自伤心，君亦多愁。","雁鱼消息几时来，才望云头。","又候潮头。"]},{"t":"江城子 春思","f":"古风","c":["花朝去了又春分。","草如茵，柳烟新。","油壁青骢，争踏武陵春。","绣暮罗衣香过处，人不见，插红裙。","纱窗寒雨最难闻。","冷炉薰，淡芳樽。","闲病闲愁，独对旧东君。","日暮捲帘南北望，魂欲化，楚山云。"]},{"t":"满江红 春闺","f":"古风","c":["玉懒香颓，支瘦腕、行行立立。","颇藜枕、鹧鸪屏外，衬花茵席。","行雨梦飞巫峡上，随风笑踏江南陌。","恨高楼、故故恼人眠，吹长笛。","揽衣起，斜阳侧。","临宝镜，修山额。","沾芙蓉粉汗，倩郎温拭。","罗带小开锦翡翠，云鬟斜插金鸂鶒。","倚香奁、一晌晚妆成，西窗黑。"]},{"t":"菩萨蛮 为陆次云题万年冰，","f":"古风","c":["几时海上凌波去。","碧云宫里偷冰柱。","携向玉台中。","光争琥珀红。","长安多热客。","把玩清心骨。","若问是何名。","多年一老兵。"]},{"t":"歌七章","f":"古风","c":["九灵山人泛东海，《麦秀》《黍离》歌慷慨。","席帽山人隐吴门，残山剩水声常吞。","二子不仕亦不死，惟有子中所为极难耳。","江西复，广东破，变姓名，北山卧。","弃妻子，浮江湘，足已折，身难藏。","使者来，引鸠觞，辞亲友，歌《七章》。","歌《七章》，悲元亡。","呜呼，元亡乃有文天祥！"]},{"t":"南陈北李","f":"古风","c":["南京有一陈，太学无弃人。","北京有一李，太学多端士。","李先生，讲《五经》，公侯环坐听《鹿鸣》。","桥门荷校辱非刑，诸生举幢呼阙廷，会昌上奏太后惊。","陈先生，考绩至，手书《四箴》返金币，招之不住守吾志。","危哉履虎幸不噬，两贤道同命则异。","君不见西市将杀薛夫子，灶下老仆哭不止。"]},{"t":"王先生","f":"古风","c":["太皇太后女尧舜，宫嫔加刃诛王振。","不见高皇竖铁牌，内宫不许干朝政？","振乎毁牌太纵横，天子亦呼王先生。","先生一开口，天子下殿走。","蒙尘事可哀，夺门名亦丑。","横尸百万谁首戎，天子犹念先生功。","诏取沈香雕小像，巍峨寺额称旌忠。"]},{"t":"北狩","f":"古风","c":["大明天子云端坐，谁人推向沙场堕？","窝儿帐外黄龙卧，赤光笼罩望如火。","也先耶？","伯颜耶？","大同赛刊耶？","今日宰牛，明日宰马。","大妇唱歌，小妻洗斝。","风吹草低，橐驼盈野。","送君还归，群呼者者。","君不见周骊山、鲁鸲鹆，青衣行酒怀悯辱，五国城中徽钦哭。"]},{"t":"对山救我","f":"古风","c":["刘家老公性烈火，满朝公卿锒铛锁。","磨刀杀李崆峒，惟有对山能救我。","对山慨应真吾事，骑马上门谒中贵。","今日何好风，吹得状元至？","老公倒屣小珰跪，焚香把酒劝公醉。","醉公酒，我不辞，我一言，公三思。","力士肯为太白屈，此事非公谁能之？","老公笑请先生坐，当为狂生免其祸。","解衣脱帽为公舞，哺糟啜醨无不可。","明年天子诛老公，朝里交章荐崆峒。","可怜对山罢官去，一身零落污泥中。","对山救我李北地，谁救对山康武功？","且呼少年共豪饮，手弹琵琶曲未终。","琵琶嘈嘈弦何急，声声似诉负情侬。"]},{"t":"铁夫人","f":"古风","c":["武皇南巡臣拜杖，良人系狱妾心丧。","妾家儿女本无知，焚香吁天诚有之。","逻骑缚来坐咒诅，夫妇牵连入圜土。","妾今有身不任刑，惟拚一死谢夫君。","情辞慷慨相决绝，法吏满堂谁忍闻。","一旦天恩并放归，都人夹道尽沾衣。","还将前日香重爇，长祝君王罢六飞。","林大辂谏武宗南巡，下狱，"]},{"t":"新都叹","f":"七言古诗","c":["新都才人官玉局，入朝手撼天门哭。","相公之子状元郎，杖血淋漓投永昌。","永昌市上拥诸妓，簪花涂粉双丫髻。","白绫新裓彩毫光，酒酣起舞龙蛇字。","蛮童笑杀老颠狂，万里云南作醉乡。","相思独有深闺妇，盼断金鸡下夜郎。"]},{"t":"河套冤","f":"古风","c":["严夏两家鸡相斗，曾铣仇鸾袒左右。","严鸡方胜夏鸡孤，铣欲劾鸾何为乎？","套未复，身先死。","朝玺书，暮西市。","将军横尸何足言，宰相骈首宁无冤？","君莫哭，君不见金牌召后风波狱。"]},{"t":"臣夫表","f":"古风","c":["臣夫在狱十六年，家有老亲八十九。","臣妻置妾未相见，旅舍凄凉誓同守。","欲归则弃夫，欲留则违舅。","弃夫断饘粥，违舅阙箕帚。","臣愿代系狱，放夫暂回首。","生当还囹圄，死得瘗陇亩。","此疏不忍读，读之血盈斗。","弥留始解网，覆盆既已久。","呜呼！","夫忠臣，妻烈妇，可与苏张三不朽。"]},{"t":"吊南塘","f":"古风","c":["副将军，在南郡，杀倭全用鸳鸯阵。","大将军，在蓟门，阅兵争跳龙虎屯。","结发从戎无不可，筹边更重北门锁。","万里长城背朔方，伏波只看飞鸢堕。","江陵已没二华亡，倚剑悲歌古战场。","白袷角巾归第日，路人谁识戚南塘？","惟有白头旧部曲，西风落日叹《烧荒》。"]},{"t":"嘒鸾火","f":"七言古诗","c":["贵妃方辞坤宁去，选侍旋向乾清住。","封后封妃许不许，手提哥儿咄咄语。","防微杜渐争移宫，专制垂帘事不同。","先皇末命犹在耳，嘒鸾一火何匆匆！","雉经入井传闻异，保全母子无他意。","宫闱骨肉贵调停，难将国事行家事。","诸君莫争郑与李，奉圣夫人又至矣！"]},{"t":"赵高传","f":"古风","c":["委鬼当头坐，茄花满地红。","赵娆曹节私相通，老祖太太配公公。","月华门前车斗风，涿州道上马游龙。","内操挝鼓鸣刀弓，犴狴流血朝班空。","祠堂昭德兼崇功，干儿义子多如虫。","读史至此惟三叹，殆哉岌岌将作难！","满朝弹章君不见，中宫独看《赵高传》。"]},{"t":"思陵痛","f":"古风","c":["思陵在位十七载，四海分崩成瓦解。","去年失楚今失秦，大梁水决武昌焚。","虎豹九关谁与守，三军倒戈百姓走。","君王仗剑死煤山，母后宫中殉玉环。","桐棺一寸道旁置，故老行人多掩涕。","入庙应呼十四皇，儿家何罪致天亡？","新鬼号咷旧鬼哭，钟虡惨裂灯无光。","高勿哀，文勿怒，自古兴亡有天数，顺处得来顺处去。","君不见宋家遗骨瘗冬青，昌平郁郁松楸树。"]},{"t":"民谣","f":"古风","c":["急丈田，长洲县。","田几何，百馀万。","奉部文，一年限。","朝廷丈田除浮粮，浮粮若除须补亡。","下跨河水上山冈，菜畦菱荡都抵当。","插旗四角周中央，男奔女走群慞惶。","上官督县令，县令责里正。","里正不识弓尺寸，转雇狙狯代持筹，长短方圆一手定。","一手定，一手更。","私田缩，官田盈。","移重挪轻无不有，田主瞠眼不敢争。","县家覆丈岂能遍，但取溢额可考成。","急丈田，限一年。","官经票，吏索钱。","官田未见增什一，民钱已闻费万千。","君不见一县图书七百四十一，日造黄册堆积高于山。"]},{"t":"蓟州小病","f":"五言律诗","c":["及予回马首，犹尔滞渔阳。","一病家千里，孤灯泪万行。","道途横枳棘，天地日冰霜。","苦忆柴门卧，山妻检药囊。"]},{"t":"送曾道扶司李汉中","f":"七言律诗","c":["江陵驿路满梅花，计日连云出谷斜。","大丙山高环二华，五丁峡远接三巴。","蒲鞭宽厚随羌俗，骢马威仪近汉家。","更上陈仓怀古迹，武侯残壁起悲笳。"]},{"t":"别长安五首 其一","f":"七言律诗","c":["只合渔樵老此身，底须辛苦入风尘？","一官未许因人热，十口翻成为仕贫。","阊阖天高逢鬼谒，江湘地远逐孤臣。","非关圣世簪缨短，为有青山待逸民。"]},{"t":"别长安五首 其二","f":"七言律诗","c":["朅来来吊望高台，台上黄金真可哀。","一代贤良《卜式传》，千秋流涕贾生才。","狺狺多口何为者，衮衮诸公安在哉？","燕市遨游今不见，吴门变姓且归来。"]},{"t":"别长安五首 其三","f":"七言律诗","c":["十年踪迹漫劳劳，风雨周游有敝袍。","短棹独临沧海阔，单车直上太行高。","穷途恸哭谁哀阮，荒径欣奔自拟陶。","且待向平婚嫁毕，指挥五岳属吾曹。"]},{"t":"别长安五首 其四","f":"楚辞体","c":["不如归去不如归，归去来兮知昨非。","千里壮心天马下，一朝适意野鸥飞。","焚书并瘗珊瑚笔，解绂先裁薜荔衣。","犹有吴钩抛未得，酒酣常舞钓鱼矶。"]},{"t":"别长安五首 其五","f":"七言律诗","c":["葑水城南一草堂，莳花修竹自幽芳。","老妻酿秫藏盈斗，儿子摊书读几行。","有客日来谈鬼魅，先生夜梦见羲皇。","出门莫向长安笑，曾在长安望故乡。"]},{"t":"题韩蕲王庙","f":"七言律诗","c":["忠武勋名百战回，西湖跨蹇且衔杯。","英雄短气莫须有，明哲保身归去来。","夜月灵旗摇铁瓮，秋风石马上琴台。","千年遗庙还香火，杜宇冬青正可哀。"]},{"t":"生日志感","f":"七言律诗","c":["半百年过意不如，看云藜仗倚荒庐。","平生最拙惟谋食，一事差强已废书。","萧瑟江关哀庾信，飘摇风树泣皋鱼。","何当燕市寻屠狗，洒酒荒天吊望诸。"]},{"t":"登天宇浮屠绝顶望海","f":"七言律诗","c":["兴至超然到上头，凭虚萧瑟见高秋。","诸天冥冥人非想，大地茫茫我亦愁。","俯听苍蝇喧万瓦，遥看白马走中流。","海神未许探幽窟，倏忽风烟起蜃楼。"]},{"t":"闻鹧鸪","f":"七言绝句","c":["鹧鸪声里夕阳西，陌上征人首尽低。","遍地关山行不得，为谁辛苦尽情啼？"]},{"t":"雨夜候既庭舟不至邻舟有吹笛而歌者二首 其一","f":"七言绝句","c":["风雨潇潇打布篷，横舟相失玉河中。","天南一望云千里，嘹呖三更叫断鸿。"]},{"t":"雨夜候既庭舟不至邻舟有吹笛而歌者二首 其二","f":"七言绝句","c":["谁家吹笛按吴歌，听罢凄然唤奈何。","此夜青衫知更湿，流河驿畔雨声多。"]}]};